/* Spell reference data for index.html (kept in its own file so browsers
   cache it separately from the app code, which changes more often). */
const SPELL_DB = {"Acid Splash":{"school":"Conjuration","castTime":"1 action","range":"60 ft","duration":"Instantaneous","components":"V, S","desc":"You hurl a bubble of acid. Choose one or two creatures within range within 5 feet of each other. Each must succeed on a Dexterity save or take 1d6 acid damage. Damage increases by 1d6 at 5th (2d6), 11th (3d6), and 17th level (4d6)."},"Blade Ward":{"school":"Abjuration","castTime":"1 action","range":"Self","duration":"1 round","components":"V, S","desc":"Until the end of your next turn, you have resistance against bludgeoning, piercing, and slashing damage dealt by weapon attacks."},"Chill Touch":{"school":"Necromancy","castTime":"1 action","range":"120 ft","duration":"1 round","components":"V, S","desc":"Create a ghostly skeletal hand. Make a ranged spell attack. On a hit, the target takes 1d8 necrotic damage and can't regain hit points until the start of your next turn. Undead have disadvantage on attack rolls against you. Damage increases by 1d8 at 5th, 11th, and 17th level."},"Create Bonfire":{"school":"Conjuration","castTime":"1 action","range":"60 ft","duration":"Conc, up to 1 min","components":"V, S","desc":"You create a bonfire on ground you can see. Any creature in the bonfire's space when you cast must succeed on a Dexterity save or take 1d8 fire damage. A creature that moves into it or ends its turn there also makes the save. Damage increases by 1d8 at 5th, 11th, and 17th level."},"Dancing Lights":{"school":"Evocation","castTime":"1 action","range":"120 ft","duration":"Conc, up to 1 min","components":"V, S, M","desc":"You create up to four torch-sized lights within range. You can combine them into a Medium humanoid shape. As a bonus action, move them up to 60 ft to a new spot within range."},"Druidcraft":{"school":"Transmutation","castTime":"1 action","range":"30 ft","duration":"Instantaneous","components":"V, S","desc":"Whispering to the spirits of nature, create a tiny harmless effect: predict weather, make a flower bloom, create a gentle breeze, light or snuff a small flame, or cause leaves to rustle."},"Eldritch Blast":{"school":"Evocation","castTime":"1 action","range":"120 ft","duration":"Instantaneous","components":"V, S","desc":"A beam of crackling energy streaks toward a creature. Make a ranged spell attack. On a hit, the target takes 1d10 force damage. Additional beams at 5th (2), 11th (3), and 17th level (4); each beam requires its own attack roll."},"Fire Bolt":{"school":"Evocation","castTime":"1 action","range":"120 ft","duration":"Instantaneous","components":"V, S","desc":"You hurl a mote of fire. Make a ranged spell attack. On a hit, the target takes 1d10 fire damage. Flammable objects that aren't worn are ignited. Damage increases by 1d10 at 5th (2d10), 11th (3d10), and 17th level (4d10)."},"Friends":{"school":"Enchantment","castTime":"1 action","range":"Self","duration":"Conc, up to 1 min","components":"S, M","desc":"For the duration, you have advantage on all Charisma checks directed at one creature. When the spell ends, the creature realizes you used magic on it and becomes hostile."},"Frostbite":{"school":"Evocation","castTime":"1 action","range":"60 ft","duration":"Instantaneous","components":"V, S","desc":"You cause numbing frost to form on a creature. The target must succeed on a Constitution save or take 1d6 cold damage and have disadvantage on its next weapon attack roll. Damage increases by 1d6 at 5th, 11th, and 17th level."},"Guidance":{"school":"Divination","castTime":"1 action","range":"Touch","duration":"Conc, up to 1 min","components":"V, S","desc":"Once before the spell ends, the target can roll a d4 and add the number to one ability check of its choice."},"Gust":{"school":"Transmutation","castTime":"1 action","range":"30 ft","duration":"Instantaneous","components":"V, S","desc":"You seize the air and compel it to: push a creature 5 ft (Strength save), push an object 10 ft, or create a harmless sensory effect."},"Infestation":{"school":"Conjuration","castTime":"1 action","range":"30 ft","duration":"Instantaneous","components":"V, S, M","desc":"A cloud of parasites appears on a creature. The target must succeed on a Constitution save or take 1d6 poison damage and move 5 ft in a random direction."},"Light":{"school":"Evocation","castTime":"1 action","range":"Touch","duration":"1 hour","components":"V, M","desc":"You touch one object. Until the spell ends, it sheds bright light in a 20-foot radius and dim light for an additional 20 feet."},"Mage Hand":{"school":"Conjuration","castTime":"1 action","range":"30 ft","duration":"1 minute","components":"V, S","desc":"A spectral floating hand appears. Use it to manipulate objects, open doors/containers, stow or retrieve items, or pour a vial. It can't attack, activate magic items, or carry more than 10 pounds."},"Mending":{"school":"Transmutation","castTime":"1 minute","range":"Touch","duration":"Instantaneous","components":"V, S, M","desc":"Repairs a single break or tear in an object you touch, as long as the break is no larger than 1 foot."},"Message":{"school":"Transmutation","castTime":"1 action","range":"120 ft","duration":"1 round","components":"V, S, M","desc":"You whisper a message to a creature. Only that target hears it and can reply in a whisper that only you hear."},"Minor Illusion":{"school":"Illusion","castTime":"1 action","range":"30 ft","duration":"1 minute","components":"S, M","desc":"You create a sound or image of an object within range. A creature can use an action to examine the illusion (Investigation vs spell save DC) to determine it's an illusion."},"Mold Earth":{"school":"Transmutation","castTime":"1 action","range":"30 ft","duration":"Instantaneous or 1 hr","components":"S","desc":"You choose a 5-foot-cube of earth and cause one of: excavate it, change its color/texture for 1 hour, or cause shapes/text to form on it for 1 hour."},"Poison Spray":{"school":"Conjuration","castTime":"1 action","range":"10 ft","duration":"Instantaneous","components":"V, S","desc":"You project a puff of noxious gas. The creature must succeed on a Constitution save or take 1d12 poison damage. Damage increases by 1d12 at 5th, 11th, and 17th level."},"Prestidigitation":{"school":"Transmutation","castTime":"1 action","range":"10 ft","duration":"Up to 1 hour","components":"V, S","desc":"A minor magical trick. Create a sensory effect, light/snuff a flame, clean or soil an object, chill/warm/flavor material, color a surface, or create a small trinket or image. Up to 3 non-instantaneous effects active at once."},"Produce Flame":{"school":"Conjuration","castTime":"1 action","range":"Self","duration":"10 minutes","components":"V, S","desc":"A flame appears in your hand. You can hurl it at a creature (ranged spell attack, 1d8 fire damage) ending the spell. Damage increases by 1d8 at 5th, 11th, and 17th level."},"Ray of Frost":{"school":"Evocation","castTime":"1 action","range":"60 ft","duration":"Instantaneous","components":"V, S","desc":"Make a ranged spell attack. On a hit, the target takes 1d8 cold damage and its speed is reduced by 10 ft until the start of your next turn. Damage increases by 1d8 at 5th, 11th, and 17th level."},"Sacred Flame":{"school":"Evocation","castTime":"1 action","range":"60 ft","duration":"Instantaneous","components":"V, S","desc":"The target must succeed on a Dexterity save or take 1d8 radiant damage. The target gains no benefit from cover for this saving throw. Damage increases by 1d8 at 5th, 11th, and 17th level."},"Shape Water":{"school":"Transmutation","castTime":"1 action","range":"30 ft","duration":"Instantaneous or 1 hr","components":"S","desc":"Choose a 5-foot cube of water: move it up to 25 ft, change its flow, freeze it for 1 hour, or change its color/opacity for 1 hour."},"Shillelagh":{"school":"Transmutation","castTime":"1 bonus action","range":"Touch","duration":"1 minute","components":"V, S, M","desc":"A club or quarterstaff you hold is imbued with nature's power. Use your spellcasting ability instead of Strength for attacks and damage with it, and its damage die becomes a d8."},"Shocking Grasp":{"school":"Evocation","castTime":"1 action","range":"Touch","duration":"Instantaneous","components":"V, S","desc":"Make a melee spell attack (advantage if target wears metal armor). On a hit, 1d8 lightning damage and the target can't take reactions until the start of its next turn. Damage increases by 1d8 at 5th, 11th, 17th level."},"Spare the Dying":{"school":"Necromancy","castTime":"1 action","range":"Touch","duration":"Instantaneous","components":"V, S","desc":"You touch a living creature at 0 HP. The creature becomes stable. No effect on undead or constructs."},"Thaumaturgy":{"school":"Transmutation","castTime":"1 action","range":"30 ft","duration":"Up to 1 minute","components":"V","desc":"You manifest a minor wonder: your voice booms, flames flicker, tremors shake the ground, your eyes turn black, doors fly open/slam shut, or an eerie sound emanates. Up to 3 effects active at once."},"Thunderclap":{"school":"Evocation","castTime":"1 action","range":"5 ft","duration":"Instantaneous","components":"S","desc":"You create a burst of thunderous sound audible 100 ft away. Each creature within range must succeed on a Constitution save or take 1d6 thunder damage."},"Toll the Dead":{"school":"Necromancy","castTime":"1 action","range":"60 ft","duration":"Instantaneous","components":"V, S","desc":"A dolorous bell fills the air. The target must succeed on a Wisdom save or take 1d8 necrotic damage, or 1d12 if the target is missing any hit points. Damage increases by one die at 5th, 11th, and 17th level."},"True Strike":{"school":"Divination","castTime":"1 action","range":"30 ft","duration":"Conc, up to 1 round","components":"S","desc":"You gain a brief insight into the target's defenses. On your next turn, you gain advantage on your first attack roll against the target."},"Vicious Mockery":{"school":"Enchantment","castTime":"1 action","range":"60 ft","duration":"Instantaneous","components":"V","desc":"You unleash insults laced with enchantments. The target must succeed on a Wisdom save or take 1d4 psychic damage and have disadvantage on its next attack roll. Damage increases by 1d4 at 5th, 11th, and 17th level."},"Word of Radiance":{"school":"Evocation","castTime":"1 action","range":"5 ft","duration":"Instantaneous","components":"V, M","desc":"You utter a divine word, and radiance erupts from you. Each creature of your choice within range must succeed on a Constitution save or take 1d6 radiant damage. Damage increases by 1d6 at 5th, 11th, and 17th level."},"Absorb Elements":{"school":"Abjuration","castTime":"1 reaction","range":"Self","duration":"1 round","components":"S","desc":"When you take acid, cold, fire, lightning, or thunder damage, you gain resistance to that damage type until the start of your next turn, and your first melee attack on your next turn deals an extra 1d6 damage of that type per spell slot level."},"Alarm":{"school":"Abjuration","castTime":"1 minute (ritual)","range":"30 ft","duration":"8 hours","components":"V, S, M","desc":"Set an alarm on a door, window, or area up to a 20-foot cube. A mental alarm alerts you, or an audible alarm sounds, when a Tiny or larger creature touches or enters the warded area."},"Animal Friendship":{"school":"Enchantment","castTime":"1 action","range":"30 ft","duration":"24 hours","components":"V, S, M","desc":"You convince a beast that you mean it no harm. The target must succeed on a Wisdom save or be charmed by you for the spell's duration."},"Armor of Agathys":{"school":"Abjuration","castTime":"1 action","range":"Self","duration":"1 hour","components":"V, S, M","desc":"A protective magical force surrounds you, granting 5 temporary HP. If a creature hits you while you have these temp HP, it takes 5 cold damage. Both values increase by 5 per slot level above 1st."},"Arms of Hadar":{"school":"Conjuration","castTime":"1 action","range":"Self (10-ft radius)","duration":"Instantaneous","components":"V, S","desc":"Tendrils of dark energy erupt from you. Each creature within 10 ft must make a Strength save or take 2d6 necrotic damage and lose reactions until its next turn. Half damage on success. +2d6 per slot level above 1st."},"Bane":{"school":"Enchantment","castTime":"1 action","range":"30 ft","duration":"Conc, up to 1 min","components":"V, S, M","desc":"Up to three creatures must succeed on a Charisma save or subtract 1d4 from attack rolls and saving throws. One additional creature per slot level above 1st."},"Bless":{"school":"Enchantment","castTime":"1 action","range":"30 ft","duration":"Conc, up to 1 min","components":"V, S, M","desc":"Bless up to three creatures. Whenever a target makes an attack roll or saving throw, it rolls a d4 and adds it to the result. One additional creature per slot level above 1st."},"Burning Hands":{"school":"Evocation","castTime":"1 action","range":"Self (15-ft cone)","duration":"Instantaneous","components":"V, S","desc":"A thin sheet of flame shoots from your fingertips. Each creature in a 15-foot cone makes a Dexterity save, taking 3d6 fire damage on a failure (half on success). +1d6 per slot level above 1st."},"Charm Person":{"school":"Enchantment","castTime":"1 action","range":"30 ft","duration":"1 hour","components":"V, S","desc":"Attempt to charm a humanoid. It makes a Wisdom save (advantage if in combat). On a fail, it's charmed and regards you as a friendly acquaintance. It knows you charmed it when the spell ends. One additional target per slot level above 1st."},"Chromatic Orb":{"school":"Evocation","castTime":"1 action","range":"90 ft","duration":"Instantaneous","components":"V, S, M (diamond worth 50 gp)","desc":"You hurl a sphere of energy. Choose acid, cold, fire, lightning, poison, or thunder. Make a ranged spell attack; on a hit, the target takes 3d8 damage of the chosen type. +1d8 per slot level above 1st."},"Color Spray":{"school":"Illusion","castTime":"1 action","range":"Self (15-ft cone)","duration":"1 round","components":"V, S, M","desc":"Roll 6d10 — that's how many HP of creatures this spell can affect. Starting with the lowest HP creature in the cone, each creature is blinded until the end of your next turn if its HP is within the remaining total. +2d10 per slot level above 1st."},"Command":{"school":"Enchantment","castTime":"1 action","range":"60 ft","duration":"1 round","components":"V","desc":"Speak a one-word command to a creature within range. The target must succeed on a Wisdom save or follow the command on its next turn: Approach, Drop, Flee, Grovel, or Halt. One additional target per slot level above 1st."},"Compelled Duel":{"school":"Enchantment","castTime":"1 bonus action","range":"30 ft","duration":"Conc, up to 1 min","components":"V","desc":"You compel a creature to fight you. The target makes a Wisdom save or is drawn to you, must attack you if able, and has disadvantage on attacks against others."},"Comprehend Languages":{"school":"Divination","castTime":"1 action (ritual)","range":"Self","duration":"1 hour","components":"V, S, M","desc":"You understand any spoken language you hear and any written language you see (must touch the surface). Takes about 1 minute to read one page."},"Cure Wounds":{"school":"Evocation","castTime":"1 action","range":"Touch","duration":"Instantaneous","components":"V, S","desc":"A creature you touch regains 1d8 + your spellcasting ability modifier hit points. No effect on undead or constructs. +1d8 per slot level above 1st."},"Detect Magic":{"school":"Divination","castTime":"1 action (ritual)","range":"Self","duration":"Conc, up to 10 min","components":"V, S","desc":"For the duration, you sense the presence of magic within 30 feet. You can use your action to see a faint aura around any visible magic bearer and learn its school of magic."},"Disguise Self":{"school":"Illusion","castTime":"1 action","range":"Self","duration":"1 hour","components":"V, S","desc":"You make yourself look different. You can seem 1 foot shorter or taller. The disguise is illusory and doesn't withstand physical inspection."},"Dissonant Whispers":{"school":"Enchantment","castTime":"1 action","range":"60 ft","duration":"Instantaneous","components":"V","desc":"You whisper a discordant melody only one creature can hear. It must make a Wisdom save or take 3d6 psychic damage and use its reaction to move away from you as fast as possible. Half damage, no movement on a success. +1d6 per slot level above 1st."},"Divine Favor":{"school":"Evocation","castTime":"1 bonus action","range":"Self","duration":"Conc, up to 1 min","components":"V, S","desc":"Your weapon attacks deal an extra 1d4 radiant damage on a hit."},"Entangle":{"school":"Conjuration","castTime":"1 action","range":"90 ft","duration":"Conc, up to 1 min","components":"V, S","desc":"Grasping weeds and vines sprout in a 20-foot square. The area is difficult terrain. Each creature there when you cast must succeed on a Strength save or be restrained. Restrained creatures can use an action to make a Strength check vs your spell save DC."},"Expeditious Retreat":{"school":"Transmutation","castTime":"1 bonus action","range":"Self","duration":"Conc, up to 10 min","components":"V, S","desc":"When you cast it, and as a bonus action each turn until the spell ends, you can take the Dash action."},"Faerie Fire":{"school":"Evocation","castTime":"1 action","range":"60 ft","duration":"Conc, up to 1 min","components":"V","desc":"Each object in a 20-foot cube and any creature in the area must succeed on a Dexterity save or be outlined in light. Attack rolls against affected creatures have advantage, and they can't benefit from invisibility."},"False Life":{"school":"Necromancy","castTime":"1 action","range":"Self","duration":"1 hour","components":"V, S, M","desc":"You gain 1d4+4 temporary hit points for the duration. +5 temporary hit points per slot level above 1st."},"Feather Fall":{"school":"Transmutation","castTime":"1 reaction","range":"60 ft","duration":"1 minute","components":"V, M","desc":"Choose up to five falling creatures. Each creature's rate of descent slows to 60 feet per round. No falling damage if it lands before the spell ends."},"Find Familiar":{"school":"Conjuration","castTime":"1 hour (ritual)","range":"10 ft","duration":"Instantaneous","components":"V, S, M (10 gp of charcoal, herbs, incense)","desc":"You gain the service of a familiar. You can communicate telepathically within 100 feet, see through its eyes, and cast touch spells through it. The familiar can't attack. When it drops to 0 HP it disappears and can be resummoned."},"Fog Cloud":{"school":"Conjuration","castTime":"1 action","range":"120 ft","duration":"Conc, up to 1 hr","components":"V, S","desc":"A 20-foot-radius sphere of fog spreads around corners. The area is heavily obscured. +20-foot radius per slot level above 1st."},"Gift of Alacrity (Dunamancy)":{"school":"Divination","castTime":"1 minute","range":"Touch","duration":"8 hours","components":"V, S","desc":"You touch a willing creature. For the duration, the target can add 1d8 to its initiative rolls."},"Goodberry":{"school":"Transmutation","castTime":"1 action","range":"Touch","duration":"Instantaneous","components":"V, S, M","desc":"Up to ten berries appear, infused with magic. A creature can eat one to regain 1 HP. Each berry provides nourishment for one day. Berries lose potency after 24 hours."},"Grease":{"school":"Conjuration","castTime":"1 action","range":"60 ft","duration":"1 minute","components":"V, S, M","desc":"Slick grease covers a 10-foot square. The area is difficult terrain. Any creature in the area when you cast must succeed on a Dexterity save or fall prone. Entering creatures must also save."},"Guiding Bolt":{"school":"Evocation","castTime":"1 action","range":"120 ft","duration":"1 round","components":"V, S","desc":"Make a ranged spell attack. On a hit, the target takes 4d6 radiant damage, and the next attack roll against the target before the end of your next turn has advantage. +1d6 per slot level above 1st."},"Healing Word":{"school":"Evocation","castTime":"1 bonus action","range":"60 ft","duration":"Instantaneous","components":"V","desc":"A creature within range regains 1d4 + your spellcasting ability modifier hit points. No effect on undead or constructs. +1d4 per slot level above 1st."},"Hellish Rebuke":{"school":"Evocation","castTime":"1 reaction","range":"60 ft","duration":"Instantaneous","components":"V, S","desc":"When damaged by a creature within range, you point your finger at it. It must make a Dexterity save, taking 2d10 fire damage on failure (half on success). +1d10 per slot level above 1st."},"Heroism":{"school":"Enchantment","castTime":"1 action","range":"Touch","duration":"Conc, up to 1 min","components":"V, S","desc":"A willing creature you touch is immune to being frightened and gains temporary HP equal to your spellcasting modifier at the start of each of its turns. One additional creature per slot level above 1st."},"Hex":{"school":"Enchantment","castTime":"1 bonus action","range":"90 ft","duration":"Conc, up to 1 hr","components":"V, S, M","desc":"You curse a creature. Until the spell ends, you deal an extra 1d6 necrotic damage whenever you hit it with an attack. Choose one ability: the target has disadvantage on checks using that ability. Moves to a new creature if target drops to 0 HP (bonus action)."},"Hunter's Mark":{"school":"Divination","castTime":"1 bonus action","range":"90 ft","duration":"Conc, up to 1 hr","components":"V","desc":"You mark a creature as your quarry. Until the spell ends, you deal an extra 1d6 damage whenever you hit it with a weapon attack, and you have advantage on Perception and Survival checks to find it."},"Identify":{"school":"Divination","castTime":"1 minute (ritual)","range":"Touch","duration":"Instantaneous","components":"V, S, M (a pearl worth 100 gp)","desc":"Learn an object's properties, how to use them, whether it requires attunement, and how many charges it has. Also learn if any spells are affecting the item."},"Inflict Wounds":{"school":"Necromancy","castTime":"1 action","range":"Touch","duration":"Instantaneous","components":"V, S","desc":"Make a melee spell attack. On a hit, the target takes 3d10 necrotic damage. +1d10 per slot level above 1st."},"Jump":{"school":"Transmutation","castTime":"1 action","range":"Touch","duration":"1 minute","components":"V, S, M","desc":"The creature's jump distance is tripled until the spell ends."},"Longstrider":{"school":"Transmutation","castTime":"1 action","range":"Touch","duration":"1 hour","components":"V, S, M","desc":"The target's speed increases by 10 feet until the spell ends. One additional creature per slot level above 1st."},"Mage Armor":{"school":"Abjuration","castTime":"1 action","range":"Touch","duration":"8 hours","components":"V, S, M (a piece of cured leather)","desc":"You touch a willing creature not wearing armor. Its base AC becomes 13 + its Dexterity modifier. The spell ends if the target dons armor or you dismiss it."},"Magic Missile":{"school":"Evocation","castTime":"1 action","range":"120 ft","duration":"Instantaneous","components":"V, S","desc":"You create three glowing darts of magical force, each dealing 1d4+1 force damage. The darts all strike simultaneously. You create one additional dart per slot level above 1st."},"Protection from Evil and Good":{"school":"Abjuration","castTime":"1 action","range":"Touch","duration":"Conc, up to 10 min","components":"V, S, M","desc":"One willing creature is protected against aberrations, celestials, elementals, fey, fiends, and undead. They have disadvantage on attacks against the target and can't charm, frighten, or possess it."},"Shield":{"school":"Abjuration","castTime":"1 reaction","range":"Self","duration":"1 round","components":"V, S","desc":"When you are hit by an attack or targeted by magic missile, an invisible barrier appears. Until the start of your next turn, you have a +5 bonus to AC (including against the triggering attack) and take no damage from magic missile."},"Shield of Faith":{"school":"Abjuration","castTime":"1 bonus action","range":"60 ft","duration":"Conc, up to 10 min","components":"V, S, M","desc":"A shimmering field appears around a creature of your choice, granting it a +2 bonus to AC."},"Sleep":{"school":"Enchantment","castTime":"1 action","range":"90 ft","duration":"1 minute","components":"V, S, M","desc":"Roll 5d8; the total is how many HP of creatures this spell can affect. Starting with the lowest current HP creature, each creature in a 20-foot radius falls unconscious. Undead and charm-immune creatures aren't affected. +2d8 per slot level above 1st."},"Speak with Animals":{"school":"Divination","castTime":"1 action (ritual)","range":"Self","duration":"10 minutes","components":"V, S","desc":"You gain the ability to comprehend and verbally communicate with beasts. Their knowledge is limited, but they can give information about nearby locations and monsters."},"Thunderwave":{"school":"Evocation","castTime":"1 action","range":"Self (15-ft cube)","duration":"Instantaneous","components":"V, S","desc":"A wave of thunderous force sweeps out. Each creature in a 15-foot cube makes a Constitution save or takes 2d8 thunder damage and is pushed 10 feet (half damage, not pushed on success). Audible up to 300 feet. +1d8 per slot level above 1st."},"Witch Bolt":{"school":"Evocation","castTime":"1 action","range":"30 ft","duration":"Conc, up to 1 min","components":"V, S, M","desc":"Make a ranged spell attack. On a hit, the target takes 1d12 lightning damage; each turn you can deal 1d12 lightning damage automatically (action). Spell ends if you move out of range or use another action. +1d12 per slot level above 1st."},"Wrathful Smite":{"school":"Evocation","castTime":"1 bonus action","range":"Self","duration":"Conc, up to 1 min","components":"V","desc":"Your next melee weapon attack deals +1d6 psychic damage. If the target is a creature, it must succeed on a Wisdom save or be frightened of you until the spell ends."},"Aid":{"school":"Abjuration","castTime":"1 action","range":"30 ft","duration":"8 hours","components":"V, S, M","desc":"Choose up to three creatures. Each target's HP maximum and current HP increase by 5. +5 HP per slot level above 2nd."},"Alter Self":{"school":"Transmutation","castTime":"1 action","range":"Self","duration":"Conc, up to 1 hr","components":"V, S","desc":"Assume a different form. Choose: Aquatic Adaptation (breathe water, swim 60 ft), Change Appearance (alter appearance), or Natural Weapons (claws/fangs, 1d6 + Strength, magical)."},"Arcane Lock":{"school":"Abjuration","castTime":"1 action","range":"Touch","duration":"Until dispelled","components":"V, S, M (25 gp gold dust)","desc":"You touch a closed door, window, gate, chest, or entryway. It becomes locked and the DC to break or pick it increases by 10."},"Blindness/Deafness":{"school":"Necromancy","castTime":"1 action","range":"30 ft","duration":"1 minute","components":"V","desc":"Choose one creature and whether to blind or deafen it. The target makes a Constitution save or is affected. At the end of each of its turns, it can make another save to end the effect. One additional target per slot level above 2nd."},"Blur":{"school":"Illusion","castTime":"1 action","range":"Self","duration":"Conc, up to 1 min","components":"V","desc":"Your body becomes blurred, shifting and wavering. Any creature has disadvantage on attack rolls against you (unless it doesn't rely on sight)."},"Cloud of Daggers":{"school":"Conjuration","castTime":"1 action","range":"60 ft","duration":"Conc, up to 1 min","components":"V, S, M","desc":"You fill the air with spinning daggers in a 5-foot cube. A creature takes 4d4 slashing damage when it enters the spell's area for the first time on a turn or starts its turn there. +2d4 per slot level above 2nd."},"Darkness":{"school":"Evocation","castTime":"1 action","range":"60 ft","duration":"Conc, up to 10 min","components":"V, M","desc":"Magical darkness fills a 15-foot-radius sphere. Darkvision can't penetrate it; nonmagical light can't illuminate it."},"Darkvision":{"school":"Transmutation","castTime":"1 action","range":"Touch","duration":"8 hours","components":"V, S, M","desc":"You touch a willing creature. For the duration, it has darkvision out to 60 feet."},"Detect Thoughts":{"school":"Divination","castTime":"1 action","range":"Self","duration":"Conc, up to 1 min","components":"V, S, M","desc":"Read surface thoughts, or probe deeper (Wisdom save). Also detect sentient creatures within 30 feet you can't see."},"Enhance Ability":{"school":"Transmutation","castTime":"1 action","range":"Touch","duration":"Conc, up to 1 hr","components":"V, S, M","desc":"Choose one: Bear's Endurance (Con advantage + 2d6 temp HP), Bull's Strength (Str advantage, double carry), Cat's Grace (Dex advantage, no fall damage ≤20 ft), Eagle's Splendor (Cha advantage), Fox's Cunning (Int advantage), or Owl's Wisdom (Wis advantage)."},"Enlarge/Reduce":{"school":"Transmutation","castTime":"1 action","range":"30 ft","duration":"Conc, up to 1 min","components":"V, S, M","desc":"Enlarge: target doubles in size, advantage on Strength checks/saves, +1d4 weapon damage. Reduce: target halves in size, disadvantage on Strength checks/saves, -1d4 weapon damage."},"Flame Blade":{"school":"Evocation","castTime":"1 bonus action","range":"Self","duration":"Conc, up to 10 min","components":"V, S, M","desc":"You evoke a fiery blade in your free hand. Make a melee spell attack dealing 3d6 fire damage on a hit. Sheds bright light 10 ft, dim light 10 ft further. +1d6 damage per 2 slot levels above 2nd."},"Flaming Sphere":{"school":"Conjuration","castTime":"1 action","range":"60 ft","duration":"Conc, up to 1 min","components":"V, S, M","desc":"A 5-foot-diameter sphere of fire appears. Any creature that ends its turn within 5 feet must make a Dexterity save or take 2d6 fire damage. Move it up to 30 feet as a bonus action. +1d6 per slot level above 2nd."},"Gust of Wind":{"school":"Evocation","castTime":"1 action","range":"Self","duration":"Conc, up to 1 min","components":"V, S, M","desc":"A line of strong wind 60 feet long and 10 feet wide blasts from you. Creatures must spend 2 feet of movement per foot moved toward you. Strength save or be pushed 15 feet away."},"Heat Metal":{"school":"Transmutation","castTime":"1 action","range":"60 ft","duration":"Conc, up to 1 min","components":"V, S, M","desc":"You cause a manufactured metal object to glow red-hot. Any creature in contact with it takes 2d8 fire damage. You can deal the damage again as a bonus action. +1d8 per slot level above 2nd."},"Hold Person":{"school":"Enchantment","castTime":"1 action","range":"60 ft","duration":"Conc, up to 1 min","components":"V, S, M (a small straight piece of iron)","desc":"Choose a humanoid. It must succeed on a Wisdom save or be paralyzed. At the end of each of its turns, it can make another Wisdom save. One additional humanoid per slot level above 2nd."},"Invisibility":{"school":"Illusion","castTime":"1 action","range":"Touch","duration":"Conc, up to 1 hr","components":"V, S, M","desc":"A creature you touch becomes invisible. The spell ends for a target that attacks or casts a spell. One additional creature per slot level above 2nd."},"Knock":{"school":"Transmutation","castTime":"1 action","range":"60 ft","duration":"Instantaneous","components":"V","desc":"Choose a locked, barred, or stuck object. A lock is unlocked, a stuck or barred door is opened, or a chest is opened. Audible up to 300 feet."},"Levitate":{"school":"Transmutation","castTime":"1 action","range":"60 ft","duration":"Conc, up to 10 min","components":"V, S, M","desc":"One creature or object (up to 500 lbs) rises up to 20 feet and remains suspended. The target can move up or down (up to 20 ft per action). Unwilling creatures make a Constitution save."},"Magic Weapon":{"school":"Transmutation","castTime":"1 bonus action","range":"Touch","duration":"Conc, up to 1 hr","components":"V, S","desc":"A nonmagical weapon becomes magical with a +1 bonus to attack and damage rolls. +2 at 4th-5th level slots, +3 at 6th level+."},"Mirror Image":{"school":"Illusion","castTime":"1 action","range":"Self","duration":"1 minute","components":"V, S","desc":"Three illusory duplicates appear in your space. When a creature attacks you, roll a d20 to see if it hits a duplicate instead (AC 10 + Dex modifier). A duplicate is destroyed when hit."},"Misty Step":{"school":"Conjuration","castTime":"1 bonus action","range":"Self","duration":"Instantaneous","components":"V","desc":"Briefly surrounded by silvery mist, you teleport up to 30 feet to an unoccupied space you can see."},"Moonbeam":{"school":"Evocation","castTime":"1 action","range":"120 ft","duration":"Conc, up to 1 min","components":"V, S, M","desc":"A silvery beam of pale light shines down in a 5-foot-radius, 40-foot-high cylinder. Creatures entering or starting their turn there make a Constitution save or take 2d10 radiant damage. Shapechangers have disadvantage. +1d10 per slot level above 2nd."},"Pass without Trace":{"school":"Abjuration","castTime":"1 action","range":"Self","duration":"Conc, up to 1 hr","components":"V, S, M","desc":"A veil of shadows radiates from you. Each creature you choose within 30 feet has a +10 bonus to Stealth checks and can't be tracked except by magical means."},"Prayer of Healing":{"school":"Evocation","castTime":"10 minutes","range":"30 ft","duration":"Instantaneous","components":"V","desc":"Up to six creatures of your choice each regain 2d8 + your spellcasting modifier HP. No effect on undead or constructs. +1d8 per slot level above 2nd."},"Ray of Enfeeblement":{"school":"Necromancy","castTime":"1 action","range":"60 ft","duration":"Conc, up to 1 min","components":"V, S","desc":"Make a ranged spell attack. On a hit, the target deals only half damage with weapon attacks using Strength. The target can make a Constitution save at the end of each turn."},"Rope Trick":{"school":"Transmutation","castTime":"1 action","range":"Touch","duration":"1 hour","components":"V, S, M","desc":"You touch a length of rope up to 60 feet long. One end rises until it hangs perpendicular to the ground. At the top, an invisible extradimensional space that can hold up to 8 Medium creatures."},"Scorching Ray":{"school":"Evocation","castTime":"1 action","range":"120 ft","duration":"Instantaneous","components":"V, S","desc":"You create three rays of fire. Make a ranged spell attack for each ray; on a hit, the target takes 2d6 fire damage. One additional ray per slot level above 2nd."},"See Invisibility":{"school":"Divination","castTime":"1 action","range":"Self","duration":"1 hour","components":"V, S, M","desc":"You see invisible creatures and objects as if they were visible, and can see into the Ethereal Plane out to 60 feet."},"Shatter":{"school":"Evocation","castTime":"1 action","range":"60 ft","duration":"Instantaneous","components":"V, S, M","desc":"A sudden loud ringing erupts from a point. Each creature in a 10-foot-radius sphere makes a Constitution save or takes 3d8 thunder damage (half on success). Nonmagical objects take the damage automatically. +1d8 per slot level above 2nd."},"Silence":{"school":"Illusion","castTime":"1 action (ritual)","range":"120 ft","duration":"Conc, up to 10 min","components":"V, S","desc":"No sound can be created within or pass through a 20-foot-radius sphere. Creatures inside are immune to thunder damage, are deafened, and can't use verbal spell components."},"Spider Climb":{"school":"Transmutation","castTime":"1 action","range":"Touch","duration":"Conc, up to 1 hr","components":"V, S, M","desc":"One willing creature gains the ability to move across vertical surfaces and upside down along ceilings, while leaving hands free. Climbing speed equals walking speed."},"Spike Growth":{"school":"Transmutation","castTime":"1 action","range":"150 ft","duration":"Conc, up to 10 min","components":"V, S, M","desc":"The ground in a 20-foot radius twists and sprouts spikes. Difficult terrain. When a creature moves within the area, it takes 2d4 piercing damage for every 5 feet traveled."},"Spiritual Weapon":{"school":"Evocation","castTime":"1 bonus action","range":"60 ft","duration":"1 minute","components":"V, S","desc":"You create a floating spectral weapon. As a bonus action, move it up to 20 feet and make a melee spell attack against a creature within 5 feet. On a hit, 1d8 + spellcasting modifier force damage. +1d8 per 2 slot levels above 2nd."},"Suggestion":{"school":"Enchantment","castTime":"1 action","range":"30 ft","duration":"Conc, up to 8 hrs","components":"V, M","desc":"You suggest a course of activity to a creature that can hear and understand you. The target must make a Wisdom save or pursue the action. The spell ends if the target completes the task or takes damage."},"Web":{"school":"Conjuration","castTime":"1 action","range":"60 ft","duration":"Conc, up to 1 hr","components":"V, S, M (a bit of spiderweb)","desc":"You conjure a mass of sticky webbing filling a 20-foot cube. Difficult terrain, lightly obscured. Creatures in the area must make a Dexterity save or be restrained. Restrained creatures can make a Strength check vs your spell save DC to break free. The webs are flammable."},"Animate Dead":{"school":"Necromancy","castTime":"1 minute","range":"10 ft","duration":"Instantaneous","components":"V, S, M","desc":"Choose a pile of bones or a corpse of a Medium or Small humanoid. Your spell raises it as an undead servant (zombie or skeleton) that obeys your commands for 24 hours. Additional undead per slot level above 3rd."},"Bestow Curse":{"school":"Necromancy","castTime":"1 action","range":"Touch","duration":"Conc, up to 1 min","components":"V, S","desc":"You touch a creature; it must make a Wisdom save or become cursed. Choose one effect: disadvantage on checks/saves for one ability; disadvantage on attacks against you; must save or waste action; or +1d8 necrotic from your attacks. Duration increases with higher slots."},"Blink":{"school":"Transmutation","castTime":"1 action","range":"Self","duration":"1 minute","components":"V, S","desc":"Roll a d20 at the end of each of your turns. On an 11 or higher, you vanish to the Ethereal Plane until the start of your next turn, reappearing in an unoccupied space within 10 feet of where you left."},"Call Lightning":{"school":"Conjuration","castTime":"1 action","range":"120 ft","duration":"Conc, up to 10 min","components":"V, S","desc":"A storm cloud appears. Each turn you can call down a bolt of lightning (action); any creature within 5 feet of the target point must make a Dexterity save or take 3d10 lightning damage. +1d10 per slot level above 3rd."},"Counterspell":{"school":"Abjuration","castTime":"1 reaction","range":"60 ft","duration":"Instantaneous","components":"S","desc":"When a creature you can see within range casts a spell: if 3rd level or lower, it automatically fails. If 4th level or higher, make a spellcasting ability check (DC 10 + spell's level). On a success, the spell fails."},"Daylight":{"school":"Evocation","castTime":"1 action","range":"60 ft","duration":"1 hour","components":"V, S","desc":"A 60-foot-radius sphere of bright light spreads from a point within range. It sheds dim light for an additional 60 feet. Overlapping magical darkness is dispelled."},"Dispel Magic":{"school":"Abjuration","castTime":"1 action","range":"120 ft","duration":"Instantaneous","components":"V, S","desc":"Choose one creature, object, or magical effect. Any spell of 3rd level or lower ends automatically. For higher-level spells, make an ability check (DC 10 + spell's level). +1 automatic level per slot level above 3rd."},"Fear":{"school":"Illusion","castTime":"1 action","range":"Self (30-ft cone)","duration":"Conc, up to 1 min","components":"V, S, M","desc":"Each creature in a 30-foot cone must succeed on a Wisdom save or drop everything and become frightened. It must take the Dash action away from you on each of its turns."},"Fireball":{"school":"Evocation","castTime":"1 action","range":"150 ft","duration":"Instantaneous","components":"V, S, M (bat guano and sulfur)","desc":"A bright streak explodes into a 20-foot-radius sphere. Each creature in the area makes a Dexterity save or takes 8d6 fire damage (half on success). +1d6 per slot level above 3rd."},"Fly":{"school":"Transmutation","castTime":"1 action","range":"Touch","duration":"Conc, up to 10 min","components":"V, S, M","desc":"You touch a willing creature. The target gains a flying speed of 60 feet. One additional target per slot level above 3rd."},"Gaseous Form":{"school":"Transmutation","castTime":"1 action","range":"Touch","duration":"Conc, up to 1 hr","components":"V, S, M","desc":"You transform a willing creature into a misty cloud. It is incapacitated, can fly at 10 ft speed, and can pass through small openings. Resistance to nonmagical damage, advantage on Strength, Dexterity, and Constitution saves."},"Haste":{"school":"Transmutation","castTime":"1 action","range":"30 ft","duration":"Conc, up to 1 min","components":"V, S, M","desc":"Choose a willing creature. Until the spell ends: speed doubled, +2 AC, advantage on Dexterity saves, one additional action each turn. When the spell ends, the target can't move or take actions until after its next turn."},"Hypnotic Pattern":{"school":"Illusion","castTime":"1 action","range":"120 ft","duration":"Conc, up to 1 min","components":"S, M","desc":"A twisting pattern appears in a 30-foot cube. Creatures in the area that can see it must make a Wisdom save or become charmed and incapacitated. The effect ends for a creature if it takes damage or someone shakes it out of the trance."},"Lightning Bolt":{"school":"Evocation","castTime":"1 action","range":"Self (100-ft line)","duration":"Instantaneous","components":"V, S, M (a bit of fur and a rod of amber, crystal, or glass)","desc":"A stroke of lightning forms a line 100 feet long and 5 feet wide. Each creature in the line makes a Dexterity save, taking 8d6 lightning damage on a failure (half on success). +1d6 per slot level above 3rd."},"Mass Healing Word":{"school":"Evocation","castTime":"1 bonus action","range":"60 ft","duration":"Instantaneous","components":"V","desc":"Up to six creatures of your choice regain 1d4 + your spellcasting ability modifier HP. No effect on undead or constructs. +1d4 per slot level above 3rd."},"Plant Growth":{"school":"Transmutation","castTime":"1 action or 8 hours","range":"150 ft","duration":"Instantaneous","components":"V, S","desc":"In 1 action: plants in a 100-foot radius engorge, making it difficult terrain. In 8 hours: plants in a half-mile radius are enriched, doubling their yield for 1 year."},"Protection from Energy":{"school":"Abjuration","castTime":"1 action","range":"Touch","duration":"Conc, up to 1 hr","components":"V, S","desc":"The willing creature you touch has resistance to one damage type of your choice: acid, cold, fire, lightning, or thunder."},"Remove Curse":{"school":"Abjuration","castTime":"1 action","range":"Touch","duration":"Instantaneous","components":"V, S","desc":"All curses affecting one creature or object end. If the object is a cursed magic item, its curse remains but the spell breaks its owner's attunement to it."},"Revivify":{"school":"Necromancy","castTime":"1 action","range":"Touch","duration":"Instantaneous","components":"V, S, M (diamonds worth 300 gp, consumed)","desc":"You touch a creature that has died within the last minute. It returns to life with 1 hit point. Can't restore missing body parts."},"Sending":{"school":"Evocation","castTime":"1 action","range":"Unlimited","duration":"1 round","components":"V, S, M","desc":"You send a short message of twenty-five words or less to a familiar creature. It hears the message in its mind, recognizes you, and can answer in a like manner."},"Slow":{"school":"Transmutation","castTime":"1 action","range":"120 ft","duration":"Conc, up to 1 min","components":"V, S, M","desc":"Alter time around up to six creatures in a 40-foot cube. Each target must succeed on a Wisdom save or be slowed: speed halved, -2 to AC and Dexterity saves, can't use reactions, one action or bonus action per turn."},"Speak with Dead":{"school":"Necromancy","castTime":"1 action","range":"10 ft","duration":"10 minutes","components":"V, S, M","desc":"You grant a corpse limited sentience, allowing it to answer up to 5 questions. The corpse knows only what it knew in life, including languages spoken."},"Spirit Guardians":{"school":"Conjuration","castTime":"1 action","range":"Self (15-ft radius)","duration":"Conc, up to 10 min","components":"V, S, M","desc":"Spirits flutter around you in a 15-foot radius. Enemy creatures have halved speed in the area, and when entering or starting a turn there, must make a Wisdom save or take 3d8 radiant (or necrotic) damage. +1d8 per slot level above 3rd."},"Stinking Cloud":{"school":"Conjuration","castTime":"1 action","range":"90 ft","duration":"Conc, up to 1 min","components":"V, S, M","desc":"A 20-foot-radius sphere of nauseating gas. Heavily obscured. Any creature in the cloud must make a Constitution save each turn or spend its action retching, doing nothing else."},"Tongues":{"school":"Divination","castTime":"1 action","range":"Touch","duration":"1 hour","components":"V, M","desc":"You touch a creature. For the duration, it can understand any spoken language it hears, and when it speaks, any creature that knows at least one language understands it."},"Vampiric Touch":{"school":"Necromancy","castTime":"1 action","range":"Self","duration":"Conc, up to 1 min","components":"V, S","desc":"Make a melee spell attack. On a hit, the target takes 3d6 necrotic damage, and you regain HP equal to half the damage dealt. +1d6 per slot level above 3rd."},"Water Walk":{"school":"Transmutation","castTime":"1 action (ritual)","range":"30 ft","duration":"1 hour","components":"V, S, M","desc":"This spell grants up to ten willing creatures the ability to move across any liquid surface as if it were solid ground. Submerged creatures are carried to the surface."},"Banishment":{"school":"Abjuration","castTime":"1 action","range":"60 ft","duration":"Conc, up to 1 min","components":"V, S, M","desc":"Attempt to send one creature to another plane. The target must succeed on a Charisma save or be banished. Creatures native to this plane return nearby when the spell ends. Non-native creatures stay banished. One additional creature per slot level above 4th."},"Blight":{"school":"Necromancy","castTime":"1 action","range":"30 ft","duration":"Instantaneous","components":"V, S","desc":"Necromantic energy washes over a creature. The target makes a Constitution save or takes 8d8 necrotic damage (half on success). Plants are affected as if they failed and take maximum damage. +1d8 per slot level above 4th."},"Death Ward":{"school":"Abjuration","castTime":"1 action","range":"Touch","duration":"8 hours","components":"V, S","desc":"The first time the target would drop to 0 HP from damage, it instead drops to 1 HP and the spell ends. If subjected to an effect that would kill instantly, that effect is negated instead."},"Dimension Door":{"school":"Conjuration","castTime":"1 action","range":"500 ft","duration":"Instantaneous","components":"V","desc":"You teleport yourself and optionally one willing creature of your size or smaller to any spot within range."},"Fire Shield":{"school":"Evocation","castTime":"1 action","range":"Self","duration":"10 minutes","components":"V, S, M","desc":"Thin flame surrounds your body. Choose warm (resistance to cold, attackers take 2d8 fire) or chill (resistance to fire, attackers take 2d8 cold)."},"Freedom of Movement":{"school":"Abjuration","castTime":"1 action","range":"Touch","duration":"1 hour","components":"V, S, M","desc":"The target's movement is unaffected by difficult terrain and spells can't reduce its speed, paralyze it, or restrain it. It can spend 5 feet of movement to escape a nonmagical grapple."},"Greater Invisibility":{"school":"Illusion","castTime":"1 action","range":"Touch","duration":"Conc, up to 1 min","components":"V, S","desc":"You or a creature you touch becomes invisible until the spell ends. Attacking and casting spells does NOT end this invisibility (unlike the 2nd-level version)."},"Ice Storm":{"school":"Evocation","castTime":"1 action","range":"300 ft","duration":"Instantaneous","components":"V, S, M","desc":"Hail of rock-hard ice pounds a 20-foot-radius, 40-foot-high cylinder. Each creature makes a Dexterity save or takes 2d8 bludgeoning + 4d6 cold damage (half on success). Ground becomes difficult terrain. +1d8 per slot level above 4th."},"Phantasmal Killer":{"school":"Illusion","castTime":"1 action","range":"120 ft","duration":"Conc, up to 1 min","components":"V, S","desc":"You tap into a creature's nightmares. The target makes a Wisdom save or becomes frightened. While frightened this way, it makes a Wisdom save at the start of each turn or takes 4d10 psychic damage. Success ends the spell. +1d10 per slot level above 4th."},"Polymorph":{"school":"Transmutation","castTime":"1 action","range":"60 ft","duration":"Conc, up to 1 hr","components":"V, S, M","desc":"Transform a creature into a beast form. Unwilling creatures make a Wisdom save. The creature's statistics are replaced by those of the beast (including HP). The target reverts when it drops to 0 HP."},"Stoneskin":{"school":"Abjuration","castTime":"1 action","range":"Touch","duration":"Conc, up to 1 hr","components":"V, S, M (diamond dust worth 100 gp)","desc":"The target has resistance to nonmagical bludgeoning, piercing, and slashing damage."},"Wall of Fire":{"school":"Evocation","castTime":"1 action","range":"120 ft","duration":"Conc, up to 1 min","components":"V, S, M","desc":"A wall of fire up to 60 ft long, 20 ft high, 1 ft thick. When the wall appears, each creature in its area makes a Dexterity save or takes 5d8 fire damage. Entering the hot side also deals 5d8 fire damage. +1d8 per slot level above 4th."},"Cloudkill":{"school":"Conjuration","castTime":"1 action","range":"120 ft","duration":"Conc, up to 10 min","components":"V, S","desc":"A 20-foot-radius sphere of poisonous yellow-green fog. Heavily obscured. Moves away from you 10 feet per round. Any creature must make a Constitution save or take 5d8 poison damage (half on success). +1d8 per slot level above 5th."},"Cone of Cold":{"school":"Evocation","castTime":"1 action","range":"Self (60-ft cone)","duration":"Instantaneous","components":"V, S, M","desc":"A blast of cold air erupts from your hands. Each creature in a 60-foot cone makes a Constitution save or takes 8d8 cold damage (half on success). Killed creatures become frozen statues until they thaw. +1d8 per slot level above 5th."},"Dominate Person":{"school":"Enchantment","castTime":"1 action","range":"60 ft","duration":"Conc, up to 1 min","components":"V, S","desc":"Attempt to beguile a humanoid. It makes a Wisdom save or be charmed. While charmed, you have a telepathic link and can issue commands. It makes a new Wisdom save at the end of each of its turns."},"Flame Strike":{"school":"Evocation","castTime":"1 action","range":"60 ft","duration":"Instantaneous","components":"V, S, M","desc":"A column of divine fire roars down in a 10-foot-radius, 40-foot-high cylinder. Each creature makes a Dexterity save, taking 4d6 fire + 4d6 radiant damage on a failure (half on success). +1d6 to both types per slot level above 5th."},"Greater Restoration":{"school":"Abjuration","castTime":"1 action","range":"Touch","duration":"Instantaneous","components":"V, S, M (diamond dust worth 100 gp)","desc":"You imbue a creature with positive energy. You can reduce its exhaustion by one, end a charm/petrification/curse, fix one ability score reduction, or restore a reduced HP maximum."},"Hold Monster":{"school":"Enchantment","castTime":"1 action","range":"90 ft","duration":"Conc, up to 1 min","components":"V, S, M","desc":"Choose a creature within range. The target must succeed on a Wisdom save or be paralyzed. At the end of each of its turns, it can make another Wisdom save. Works on any creature type. One additional target per slot level above 5th."},"Mass Cure Wounds":{"school":"Evocation","castTime":"1 action","range":"60 ft","duration":"Instantaneous","components":"V, S","desc":"Choose up to six creatures in a 30-foot-radius sphere. Each regains 3d8 + your spellcasting ability modifier HP. +1d8 per slot level above 5th."},"Raise Dead":{"school":"Necromancy","castTime":"1 hour","range":"Touch","duration":"Instantaneous","components":"V, S, M (diamond worth 500 gp)","desc":"Return a creature dead no longer than 10 days to life with 1 HP. Target suffers -4 to attacks, saves, and checks, decreasing by 1 per long rest."},"Scrying":{"school":"Divination","castTime":"10 minutes","range":"Self","duration":"Conc, up to 10 min","components":"V, S, M (focus worth 1,000 gp)","desc":"See and hear a creature on the same plane. The target makes a Wisdom save (DC varies by familiarity). On a failure, you see it through an invisible sensor. The target may sense the sensor with DC 15 Perception."},"Telekinesis":{"school":"Transmutation","castTime":"1 action","range":"60 ft","duration":"Conc, up to 10 min","components":"V, S","desc":"You gain the ability to move or manipulate creatures and objects by thought. Each round, exert control on one creature or object: move a creature up to 30 feet (Strength save), or move an object up to 30 feet."},"Wall of Force":{"school":"Evocation","castTime":"1 action","range":"120 ft","duration":"Conc, up to 10 min","components":"V, S, M","desc":"An invisible wall of force springs into existence as a hemisphere, sphere, or flat surface. Nothing can physically pass through it and it is immune to all damage."},"Chain Lightning":{"school":"Evocation","castTime":"1 action","range":"150 ft","duration":"Instantaneous","components":"V, S, M","desc":"A bolt of lightning arcs toward a target, then leaps to up to three secondary targets within 30 feet of each other. Make a ranged spell attack for the primary (10d8 lightning). Secondary targets make a Dexterity save for 10d8 (half on success). +1d8 per slot level above 6th."},"Disintegrate":{"school":"Transmutation","castTime":"1 action","range":"60 ft","duration":"Instantaneous","components":"V, S, M","desc":"Make a ranged spell attack. On a hit, the target takes 10d6+40 force damage. If this reduces the target to 0 HP, it and everything nonmagical on it turns to dust. +3d6 per slot level above 6th."},"Globe of Invulnerability":{"school":"Abjuration","castTime":"1 action","range":"Self (10-ft radius)","duration":"Conc, up to 1 min","components":"V, S, M","desc":"An immobile, faintly shimmering barrier appears. Any spell of 5th level or lower cast from outside can't affect creatures or objects inside it. +1 level per slot level above 6th."},"Harm":{"school":"Necromancy","castTime":"1 action","range":"60 ft","duration":"Instantaneous","components":"V, S","desc":"The target must make a Constitution save. On a failure, the creature's HP maximum is reduced by 4d6 + your spellcasting modifier until the target finishes a long rest. The target can't regain HP exceeding this reduced maximum."},"Heal":{"school":"Evocation","castTime":"1 action","range":"60 ft","duration":"Instantaneous","components":"V, S","desc":"A creature regains 70 HP. This spell also ends blindness, deafness, and any diseases affecting the target. +10 HP per slot level above 6th."},"Heroes' Feast":{"school":"Conjuration","castTime":"10 minutes","range":"30 ft","duration":"Instantaneous","components":"V, S, M (gems worth 1,000 gp consumed)","desc":"A great feast appears. Up to 12 creatures that partake are cured of diseases/poison, immune to poison and frightened, have advantage on Wisdom saves, gain +2d10 max HP, and regain all HP. Lasts until the end of the next long rest."},"Sunbeam":{"school":"Evocation","castTime":"1 action","range":"Self (60-ft line)","duration":"Conc, up to 1 min","components":"V, S, M","desc":"A beam of brilliant light flashes from your hand. Each creature in a 5-foot-wide, 60-foot-long line makes a Constitution save or takes 6d8 radiant damage and is blinded. Undead and oozes have disadvantage. You can repeat each turn (action)."},"True Seeing":{"school":"Divination","castTime":"1 action","range":"Touch","duration":"1 hour","components":"V, S, M","desc":"The target has truesight, notices secret doors hidden by magic, and can see into the Ethereal Plane, all out to 120 feet."},"Finger of Death":{"school":"Necromancy","castTime":"1 action","range":"60 ft","duration":"Instantaneous","components":"V, S","desc":"The target makes a Constitution save. On a failure, it takes 7d8+30 necrotic damage (half on success). A humanoid killed by this spell rises as a zombie permanently under your command."},"Fire Storm":{"school":"Evocation","castTime":"1 action","range":"150 ft","duration":"Instantaneous","components":"V, S","desc":"A storm of roaring flame appears in up to ten 10-foot cubes. Each creature in the area makes a Dexterity save, taking 7d10 fire damage on a failure (half on success)."},"Forcecage":{"school":"Evocation","castTime":"1 action","range":"100 ft","duration":"1 hour","components":"V, S, M (ruby dust worth 1,500 gp)","desc":"An immovable, invisible cage of force springs into existence. Choose a barred cage (20-ft cube, 1/2-inch gaps) or a box (10-ft cube, total barrier). A creature inside can't leave by nonmagical means."},"Plane Shift":{"school":"Conjuration","castTime":"1 action","range":"Touch","duration":"Instantaneous","components":"V, S, M (tuning fork worth 250 gp attuned to the plane)","desc":"You and up to eight willing creatures are transported to a different plane. Alternatively, make a melee spell attack against an unwilling creature: on a hit, it makes a Charisma save or is transported to a random location on another plane."},"Regenerate":{"school":"Transmutation","castTime":"1 minute","range":"Touch","duration":"1 hour","components":"V, S, M","desc":"The target regains 4d8+15 HP. For the duration, it regains 1 HP at the start of each of its turns. Severed body members are restored after 2 minutes."},"Resurrection":{"school":"Necromancy","castTime":"1 hour","range":"Touch","duration":"Instantaneous","components":"V, S, M (diamond worth 1,000 gp consumed)","desc":"Return a creature dead no longer than 100 years to life with all HP. Closes all wounds, neutralizes poison, cures diseases, lifts curses, and restores missing body parts."},"Reverse Gravity":{"school":"Transmutation","castTime":"1 action","range":"100 ft","duration":"Conc, up to 1 min","components":"V, S, M","desc":"Gravity reverses in a 50-foot-radius, 100-foot-high cylinder. All creatures and objects not anchored to the ground fall upward. If they hit a solid object, they strike it as with a normal downward fall."},"True Polymorph":{"school":"Transmutation","castTime":"1 action","range":"30 ft","duration":"Conc, up to 1 hr","components":"V, S, M","desc":"Choose one creature or nonmagical object within range. Transform it into a different creature or into an object. If you concentrate for the full duration, the transformation lasts until dispelled."},"Wish":{"school":"Conjuration","castTime":"1 action","range":"Self","duration":"Instantaneous","components":"V","desc":"The mightiest mortal spell. Simply speak your desire to replicate any spell of 8th level or lower. Or create one of: 25,000 gp worth of goods, restore up to 20 creatures to full HP, transport up to 10 creatures, create an object worth up to 25,000 gp, or create an effect you describe (DM's discretion). Stress of casting may prevent casting it again."},"Animal Messenger":{"school":"Enchantment","castTime":"1 action","range":"30 feet","duration":"24 hours","components":"V, S, M","desc":"You use magic to compel a Tiny beast to deliver a message. You specify a location and a recipient, and the beast travels there as fast as it can to deliver a short message you whisper to it. The beast understands your simple instructions and will not take actions that endanger itself."},"Animal Shapes":{"school":"Transmutation","castTime":"1 action","range":"30 feet","duration":"24 hours (concentration)","components":"V, S","desc":"Your magic turns others into beasts. Choose any number of willing creatures within range that you can see. You transform each target into the form of a Large or smaller beast with a challenge rating of 4 or lower. The transformation lasts for the duration, until the target drops to 0 hit points, or until you use an action to dismiss the transformation."},"Animate Objects":{"school":"Transmutation","castTime":"1 action","range":"120 feet","duration":"1 minute (concentration)","components":"V, S","desc":"Objects come to life at your command. Choose up to ten nonmagical objects within range that are not being worn or carried. Medium objects count as two objects, Large objects count as four, and Huge objects count as eight. You can't animate any object larger than Huge. Each target animates and becomes a creature under your control until the spell ends or until reduced to 0 hit points."},"Antilife Shell":{"school":"Abjuration","castTime":"1 action","range":"Self (10-foot radius)","duration":"1 hour (concentration)","components":"V, S","desc":"A shimmering barrier extends out from you in a 10-foot radius and moves with you, remaining centered on you and hedging out creatures other than undead and constructs. The barrier lasts for the duration. The barrier prevents affected creatures from passing or reaching through it."},"Antimagic Field":{"school":"Abjuration","castTime":"1 action","range":"Self (10-foot radius)","duration":"1 hour (concentration)","components":"V, S, M","desc":"A 10-foot-radius invisible sphere of antimagic surrounds you. This area is divorced from the magical energy that suffuses the multiverse. Within the sphere, spells can't be cast, summoned creatures disappear, and even magic items become mundane."},"Arcane Eye":{"school":"Divination","castTime":"1 action","range":"30 feet","duration":"1 hour (concentration)","components":"V, S, M","desc":"You create an invisible, magical eye within range that hovers in the air for the duration. You mentally receive visual information from the eye, which has normal vision and darkvision out to 30 feet. The eye can look in every direction and can move up to 30 feet in any direction each round."},"Arcane Gate":{"school":"Conjuration","castTime":"1 action","range":"500 feet","duration":"10 minutes (concentration)","components":"V, S","desc":"You create linked teleportation portals that remain open for the duration. Choose two points on the ground that you can see, one within 10 feet of you and one within 500 feet of you. A circular portal, 10 feet in diameter, opens over each point. Any creature or object entering one portal exits from the other portal."},"Astral Projection":{"school":"Necromancy","castTime":"1 hour","range":"10 feet","duration":"Special","components":"V, S, M","desc":"You and up to eight willing creatures project your astral bodies into the Astral Plane. Each target's body is left behind in a state of suspended animation. A silver cord connects the astral body to the material body. If the cord is cut, the creature dies. The spell ends for a target when it uses an action to dismiss it."},"Augury":{"school":"Divination","castTime":"1 minute","range":"Self","duration":"Instantaneous","components":"V, S, M","desc":"By casting gem-inlaid sticks, rolling dragon bones, laying out ornate cards, or employing some other divining tool, you receive an omen from an otherworldly entity about the results of a specific course of action that you plan to take within the next 30 minutes. The DM chooses from Weal, Woe, Weal and woe, or Nothing."},"Aura of Life":{"school":"Abjuration","castTime":"1 action","range":"Self (30-foot radius)","duration":"10 minutes (concentration)","components":"V","desc":"Life-preserving energy radiates from you in a 30-foot aura. Until the spell ends, the aura moves with you, centered on you. Each nonhostile creature in the aura (including you) has resistance to necrotic damage, and its hit point maximum can't be reduced. In addition, a nonhostile, living creature regains 1 hit point when it starts its turn in the aura with 0 hit points."},"Aura of Purity":{"school":"Abjuration","castTime":"1 action","range":"Self (30-foot radius)","duration":"10 minutes (concentration)","components":"V","desc":"Purifying energy radiates from you in a 30-foot aura. Until the spell ends, the aura moves with you, centered on you. Each nonhostile creature in the aura (including you) can't become diseased, has resistance to poison damage, and has advantage on saving throws against effects that cause any of the following conditions: blinded, charmed, deafened, frightened, paralyzed, poisoned, and stunned."},"Aura of Vitality":{"school":"Evocation","castTime":"1 action","range":"Self (30-foot radius)","duration":"1 minute (concentration)","components":"V","desc":"Healing energy radiates from you in a 30-foot aura. Until the spell ends, the aura moves with you, centered on you. You can use a bonus action to cause one creature in the aura (including you) to regain 2d6 hit points."},"Awaken":{"school":"Transmutation","castTime":"8 hours","range":"Touch","duration":"Instantaneous","components":"V, S, M","desc":"After spending the casting time tracing magical pathways within a precious gemstone, you touch a Huge or smaller beast or plant. The target must have either no Intelligence score or an Intelligence of 3 or less. The target gains an Intelligence of 10 and the ability to speak one language you know. The target also gains the ability to move and act on its own."},"Banishing Smite":{"school":"Abjuration","castTime":"1 bonus action","range":"Self","duration":"1 minute (concentration)","components":"V","desc":"The next time you hit a creature with a weapon attack before this spell ends, your weapon crackles with force, and the attack deals an extra 5d10 force damage to the target. Additionally, if this attack reduces the target to 50 hit points or fewer, you banish it. If the target is native to a different plane, it disappears, returning to its home plane."},"Barkskin":{"school":"Transmutation","castTime":"1 action","range":"Touch","duration":"1 hour (concentration)","components":"V, S, M","desc":"You touch a willing creature. Until the spell ends, the target's skin has a rough, bark-like appearance, and the target's AC can't be less than 16, regardless of what kind of armor it is wearing."},"Beast Sense":{"school":"Divination","castTime":"1 action","range":"Touch","duration":"1 hour (concentration)","components":"S","desc":"You touch a willing beast. For the duration of the spell, you can use your action to see through the beast's eyes and hear what it hears, and continue to do so until you use your action to return to your normal senses."},"Blade Barrier":{"school":"Evocation","castTime":"1 action","range":"90 feet","duration":"10 minutes (concentration)","components":"V, S","desc":"You create a vertical wall of whirling, razor-sharp blades made of magical energy. The wall appears within range and lasts for the duration. You can make a straight wall up to 100 feet long, 20 feet high, and 5 feet thick, or a ringed wall up to 60 feet in diameter, 20 feet high, and 5 feet thick. The wall provides three-quarters cover to creatures behind it."},"Blinding Smite":{"school":"Evocation","castTime":"1 bonus action","range":"Self","duration":"1 minute (concentration)","components":"V","desc":"The next time you hit a creature with a melee weapon attack during this spell's duration, your weapon flares with a bright light, and the attack deals an extra 3d8 radiant damage to the target. Additionally, the target must succeed on a Constitution saving throw or be blinded until the spell ends."},"Branding Smite":{"school":"Evocation","castTime":"1 bonus action","range":"Self","duration":"1 minute (concentration)","components":"V","desc":"The next time you hit a creature with a weapon attack before this spell ends, the weapon gleams with astral radiance as you strike. The attack deals an extra 2d6 radiant damage to the target, which becomes visible if it's invisible, and the target sheds dim light in a 5-foot radius and can't become invisible until the spell ends."},"Calm Emotions":{"school":"Enchantment","castTime":"1 action","range":"60 feet","duration":"1 minute (concentration)","components":"V, S","desc":"You attempt to suppress strong emotions in a group of people. Each humanoid in a 20-foot-radius sphere centered on a point you choose within range must make a Charisma saving throw. On a failed save, you can suppress any effect causing a target to be charmed or frightened, or you can make a target indifferent about creatures of your choice that it is currently hostile toward."},"Circle of Death":{"school":"Necromancy","castTime":"1 action","range":"150 feet","duration":"Instantaneous","components":"V, S, M","desc":"A sphere of negative energy ripples out in a 60-foot-radius sphere from a point within range. Each living creature in that area must make a Constitution saving throw. A target takes 8d6 necrotic damage on a failed save, or half as much damage on a successful one. At Higher Levels: When you cast this spell using a spell slot of 7th level or higher, the damage increases by 2d6 for each slot level above 6th."},"Circle of Power":{"school":"Abjuration","castTime":"1 action","range":"Self (30-foot radius)","duration":"10 minutes (concentration)","components":"V","desc":"Divine energy radiates from you, distorting and diffusing magical energy within 30 feet of you. Until the spell ends, the sphere moves with you, centered on you. Each friendly creature in the area (including you) has advantage on saving throws against spells and other magical effects. Additionally, when an affected creature succeeds on a saving throw made against a spell or magical effect that allows a save to take only half damage, it instead takes no damage."},"Clairvoyance":{"school":"Divination","castTime":"10 minutes","range":"1 mile","duration":"10 minutes (concentration)","components":"V, S, M","desc":"You create an invisible sensor within range in a location familiar to you (a place you have visited or seen before) or in an obvious location that is unfamiliar to you (such as behind a door, around a corner, or in a grove of trees). The sensor remains in place for the duration, and it can't be attacked or otherwise interacted with. When you cast the spell, you choose seeing or hearing."},"Clone":{"school":"Necromancy","castTime":"1 hour","range":"Touch","duration":"Instantaneous","components":"V, S, M","desc":"This spell grows an inert duplicate of a living creature as a safeguard against death. This clone forms inside a sealed vessel and grows to full size and maturity after 120 days. The clone remains inert and endures indefinitely, as long as its vessel remains undisturbed. If the original creature dies, its soul transfers to the clone, provided that the soul is free and willing to return."},"Commune":{"school":"Divination","castTime":"1 minute","range":"Self","duration":"1 minute","components":"V, S, M","desc":"You contact your deity or a divine proxy and ask up to three questions that can be answered with a yes or no. You must ask your questions before the spell ends. You receive a correct answer for each question to the best of the deity's knowledge."},"Commune with Nature":{"school":"Divination","castTime":"1 minute","range":"Self","duration":"Instantaneous","components":"V, S","desc":"You briefly become one with nature and gain knowledge of the surrounding territory. In the outdoors, the spell gives you knowledge of the land within 3 miles of you. In caves and other natural underground settings, the radius is limited to 300 feet. You instantly gain knowledge of up to three facts of your choice about any of the following subjects: terrain and bodies of water, prevalent plants, minerals, animals, or peoples."},"Compulsion":{"school":"Enchantment","castTime":"1 action","range":"30 feet","duration":"1 minute (concentration)","components":"V, S","desc":"Creatures of your choice that you can see within range and that can hear you must make a Wisdom saving throw. A target automatically succeeds on this saving throw if it can't be charmed. On a failed save, a target is affected by this spell. On each of your turns until the spell ends, you can use a bonus action to designate a direction that is horizontal to you. Each affected target must use as much of its movement as possible to move in that direction on its next turn."},"Confusion":{"school":"Enchantment","castTime":"1 action","range":"90 feet","duration":"1 minute (concentration)","components":"V, S, M","desc":"This spell assaults and twists creatures' minds, spawning delusions and provoking uncontrolled action. Each creature in a 10-foot-radius sphere centered on a point you choose within range must succeed on a Wisdom saving throw when you cast this spell or be affected by it. Each affected creature is incapacitated and must roll a d10 at the start of each of its turns to determine its behavior."},"Conjure Animals":{"school":"Conjuration","castTime":"1 action","range":"60 feet","duration":"1 hour (concentration)","components":"V, S","desc":"You summon fey spirits that take the form of beasts and appear in unoccupied spaces that you can see within range. Choose one of the following options for what appears: one beast of challenge rating 2 or lower, two beasts of challenge rating 1 or lower, four beasts of challenge rating 1/2 or lower, or eight beasts of challenge rating 1/4 or lower."},"Conjure Barrage":{"school":"Conjuration","castTime":"1 action","range":"Self (60-foot cone)","duration":"Instantaneous","components":"V, S, M","desc":"You throw a nonmagical weapon or fire a piece of nonmagical ammunition into the air to create a cone of identical weapons that shoot forward and then disappear. Each creature in a 60-foot cone must succeed on a Dexterity saving throw. A creature takes 3d8 damage on a failed save, or half as much damage on a successful one. The damage type is the same as that of the weapon or ammunition used as a component."},"Conjure Celestial":{"school":"Conjuration","castTime":"1 minute","range":"90 feet","duration":"1 hour (concentration)","components":"V, S","desc":"You summon a celestial of challenge rating 4 or lower, which appears in an unoccupied space that you can see within range. The celestial disappears when it drops to 0 hit points or when the spell ends. The celestial is friendly to you and your companions for the duration."},"Conjure Elemental":{"school":"Conjuration","castTime":"1 minute","range":"90 feet","duration":"1 hour (concentration)","components":"V, S, M","desc":"You call forth an elemental servant. Choose an area of air, earth, fire, or water that fills a 10-foot cube within range. An elemental of challenge rating 5 or lower appropriate to the area you chose appears in an unoccupied space within 10 feet of it. If you lose concentration, the elemental doesn't disappear. Instead, you lose control of it, and it becomes hostile toward you."},"Conjure Fey":{"school":"Conjuration","castTime":"1 minute","range":"90 feet","duration":"1 hour (concentration)","components":"V, S","desc":"You summon a fey creature of challenge rating 6 or lower, or a fey spirit that takes the form of a beast of challenge rating 6 or lower. It appears in an unoccupied space that you can see within range. The fey creature disappears when it drops to 0 hit points or when the spell ends."},"Conjure Minor Elementals":{"school":"Conjuration","castTime":"1 minute","range":"90 feet","duration":"1 hour (concentration)","components":"V, S","desc":"You summon elementals that appear in unoccupied spaces that you can see within range. You choose one of the following options for what appears: one elemental of challenge rating 2 or lower, two elementals of challenge rating 1 or lower, four elementals of challenge rating 1/2 or lower, or eight elementals of challenge rating 1/4 or lower."},"Conjure Volley":{"school":"Conjuration","castTime":"1 action","range":"150 feet","duration":"Instantaneous","components":"V, S, M","desc":"You fire a piece of nonmagical ammunition from a ranged weapon or throw a nonmagical weapon into the air and choose a point within range. Hundreds of duplicates of the ammunition or weapon fall in a volley from above and then disappear. Each creature in a 40-foot-radius, 20-foot-high cylinder centered on that point must make a Dexterity saving throw. A creature takes 8d8 damage on a failed save, or half as much on a successful one."},"Conjure Woodland Beings":{"school":"Conjuration","castTime":"1 action","range":"60 feet","duration":"1 hour (concentration)","components":"V, S, M","desc":"You summon fey creatures that appear in unoccupied spaces that you can see within range. Choose one of the following options for what appears: one fey creature of challenge rating 2 or lower, two fey creatures of challenge rating 1 or lower, four fey creatures of challenge rating 1/2 or lower, or eight fey creatures of challenge rating 1/4 or lower."},"Contact Other Plane":{"school":"Divination","castTime":"1 minute","range":"Self","duration":"1 minute","components":"V","desc":"You mentally contact a demigod, the spirit of a long-dead sage, or some other mysterious entity from another plane. Contacting this extraplanar intelligence can strain or even break your mind. When you cast this spell, make a DC 15 Intelligence saving throw. On a failure, you take 6d6 psychic damage and are insane until you finish a long rest. On a success, you can ask the entity up to five questions."},"Contagion":{"school":"Necromancy","castTime":"1 action","range":"Touch","duration":"7 days","components":"V, S","desc":"Your touch inflicts disease. Make a melee spell attack against a creature within your reach. On a hit, you afflict the creature with a disease of your choice. The target must make a Constitution saving throw at the end of each of its turns. After failing three saves, the disease's effects last for the duration, and the creature stops making these saves. After succeeding on three saves, the creature recovers from the disease."},"Contingency":{"school":"Evocation","castTime":"10 minutes","range":"Self","duration":"10 days","components":"V, S, M","desc":"Choose a spell of 5th level or lower that you can cast, that has a casting time of 1 action, and that can target you. You cast that spell, called the contingent spell, as part of casting contingency, expending spell slots for both, but the contingent spell doesn't come into effect. Instead, it takes effect when a certain circumstance occurs."},"Continual Flame":{"school":"Evocation","castTime":"1 action","range":"Touch","duration":"Until dispelled","components":"V, S, M","desc":"A flame, equivalent in brightness to a torch, springs forth from an object that you touch. The effect looks like a regular flame, but it creates no heat and doesn't use oxygen. A continual flame can be covered or hidden but not smothered or quenched."},"Control Water":{"school":"Transmutation","castTime":"1 action","range":"300 feet","duration":"10 minutes (concentration)","components":"V, S, M","desc":"Until the spell ends, you control any freestanding water inside an area you choose that is a cube up to 100 feet on a side. You can choose from the following effects: Flood, Part Water, Redirect Flow, or Whirlpool. As a bonus action on your turn, you can repeat the same effect or choose a different one."},"Control Weather":{"school":"Transmutation","castTime":"10 minutes","range":"Self (5-mile radius)","duration":"8 hours (concentration)","components":"V, S, M","desc":"You take control of the weather within 5 miles of you for the duration. You must be outdoors to cast this spell. Moving to a place where you don't have a clear path to the sky ends the spell early. When you cast the spell, you change the current weather conditions. You can change precipitation, temperature, and wind."},"Control Winds":{"school":"Transmutation","castTime":"1 action","range":"300 feet","duration":"1 hour (concentration)","components":"V, S","desc":"You take control of the air in a 100-foot cube that you can see within range. Choose one of the following effects when you cast the spell: Gusts, Downdraft, or Updraft. While concentrating, you can change the effect as an action."},"Cordon of Arrows":{"school":"Transmutation","castTime":"1 action","range":"5 feet","duration":"8 hours","components":"V, S, M","desc":"You plant four pieces of nonmagical ammunition—arrows or crossbow bolts—in the ground within range and lay magic upon them to protect an area. Until the spell ends, whenever a creature other than you comes within 30 feet of the ammunition for the first time on a turn or ends its turn there, one piece of ammunition flies up to strike it. The creature must succeed on a Dexterity saving throw or take 1d6 piercing damage."},"Create Food and Water":{"school":"Conjuration","castTime":"1 action","range":"30 feet","duration":"Instantaneous","components":"V, S","desc":"You create 45 pounds of food and 30 gallons of water on the ground or in containers within range, enough to sustain up to fifteen humanoids or five steeds for 24 hours. The food is bland but nourishing, and spoils if uneaten after 24 hours. The water is clean and doesn't go bad."},"Create Undead":{"school":"Necromancy","castTime":"1 minute","range":"10 feet","duration":"Instantaneous","components":"V, S, M","desc":"You can cast this spell only at night. Choose up to three corpses of Medium or Small humanoids within range. Each corpse becomes a ghoul under your control. At Higher Levels: When you cast this spell using a higher level slot, you can animate more corpses or create more powerful undead."},"Create or Destroy Water":{"school":"Transmutation","castTime":"1 action","range":"30 feet","duration":"Instantaneous","components":"V, S, M","desc":"You either create or destroy water. Create Water: You create up to 10 gallons of clean water within range in an open container. Alternatively, the water falls as rain in a 30-foot cube within range, extinguishing exposed flames in the area. Destroy Water: You destroy up to 10 gallons of water in an open container within range. Alternatively, you destroy fog in a 30-foot cube within range."},"Creation":{"school":"Illusion","castTime":"1 minute","range":"30 feet","duration":"Special","components":"V, S, M","desc":"You pull wisps of shadow material from the Shadowfell to create a nonliving object of vegetable matter within range: soft goods, rope, wood, or something similar. You can also use this spell to create mineral objects such as stone, crystal, or metal. The object created must be no larger than a 5-foot cube, and the object must be of a form and material that you have seen before."},"Crown of Madness":{"school":"Enchantment","castTime":"1 action","range":"120 feet","duration":"1 minute (concentration)","components":"V, S","desc":"One humanoid of your choice that you can see within range must succeed on a Wisdom saving throw or become charmed by you for the duration. While the target is charmed in this way, a twisted crown of jagged iron appears on its head, and a madness glows in its eyes. The charmed target must use its action before moving on each of its turns to make a melee attack against a creature other than itself that you mentally choose."},"Crusaders Mantle":{"school":"Evocation","castTime":"1 action","range":"Self (30-foot radius)","duration":"1 minute (concentration)","components":"V","desc":"Holy power radiates from you in a 30-foot aura, awakening boldness in friendly creatures. Until the spell ends, the aura moves with you, centered on you. While in the aura, each nonhostile creature in the aura (including you) deals an extra 1d4 radiant damage when it hits with a weapon attack."},"Delayed Blast Fireball":{"school":"Evocation","castTime":"1 action","range":"150 feet","duration":"1 minute (concentration)","components":"V, S, M","desc":"A beam of yellow light flashes from your pointing finger, then condenses to linger at a chosen point within range as a glowing bead for the duration. When the spell ends, either because your concentration is broken or because you decide to end it, the bead blossoms with a low roar into an explosion of flame that spreads around corners. Each creature in a 20-foot-radius sphere centered on that point must make a Dexterity saving throw."},"Demiplane":{"school":"Conjuration","castTime":"1 action","range":"60 feet","duration":"1 hour","components":"S","desc":"You create a shadowy door on a flat solid surface that you can see within range. The door is large enough to allow Medium creatures to pass through unhindered. When opened, the door leads to a demiplane that appears to be an empty room 30 feet in each dimension, made of wood or stone. When the spell ends, the door disappears, and any creatures or objects inside the demiplane remain trapped there."},"Destructive Wave":{"school":"Evocation","castTime":"1 action","range":"Self (30-foot radius)","duration":"Instantaneous","components":"V","desc":"You strike the ground, creating a burst of divine energy that ripples outward from you. Each creature you choose within 30 feet of you must succeed on a Constitution saving throw or take 5d6 thunder damage, as well as 5d6 radiant or necrotic damage (your choice), and be knocked prone. A creature that succeeds on its saving throw takes half as much damage and isn't knocked prone."},"Detect Evil and Good":{"school":"Divination","castTime":"1 action","range":"Self (30-foot radius)","duration":"10 minutes (concentration)","components":"V, S","desc":"For the duration, you know if there is an aberration, celestial, elemental, fey, fiend, or undead within 30 feet of you, as well as where the creature is located. Similarly, you know if there is a place or object within 30 feet of you that has been magically consecrated or desecrated."},"Detect Poison and Disease":{"school":"Divination","castTime":"1 action","range":"Self (30-foot radius)","duration":"10 minutes (concentration)","components":"V, S, M","desc":"For the duration, you can sense the presence and location of poisons, poisonous creatures, and diseases within 30 feet of you. You also identify the kind of poison, poisonous creature, or disease in each case."},"Dispel Evil and Good":{"school":"Abjuration","castTime":"1 action","range":"Self","duration":"1 minute (concentration)","components":"V, S, M","desc":"Shimmering energy surrounds and protects you from fey, undead, and creatures originating from beyond the Material Plane. For the duration, celestials, elementals, fey, fiends, and undead have disadvantage on attack rolls against you. You can also use your action to attempt to dismiss a creature charming, frightening, or possessing you."},"Divination":{"school":"Divination","castTime":"1 action","range":"Self","duration":"Instantaneous","components":"V, S, M","desc":"Your magic and an offering put you in contact with a god or a god's servants. You ask a single question concerning a specific goal, event, or activity to occur within 7 days. The DM offers a truthful reply. The reply might be a short phrase, a cryptic rhyme, or an omen."},"Divine Word":{"school":"Evocation","castTime":"1 bonus action","range":"30 feet","duration":"Instantaneous","components":"V","desc":"You utter a divine word, imbued with the power that shaped the world at the dawn of creation. Choose any number of creatures you can see within range. Each creature that can hear you must make a Charisma saving throw. On a failed save, a creature suffers an effect based on its current hit points. Creatures with 50+ HP are deafened, 40+ HP are blinded and deafened, 30+ HP are blinded, deafened, and stunned. Below 30 HP, the creature dies instantly."},"Dominate Beast":{"school":"Enchantment","castTime":"1 action","range":"60 feet","duration":"1 minute (concentration)","components":"V, S","desc":"You attempt to bludgeon one beast's mind with your will. One beast that you can see within range must succeed on a Wisdom saving throw or be charmed by you for the duration. If you or creatures that are friendly to you are fighting it, it has advantage on the saving throw. While the beast is charmed this way, you have a telepathic link with it."},"Dominate Monster":{"school":"Enchantment","castTime":"1 action","range":"60 feet","duration":"1 hour (concentration)","components":"V, S","desc":"You attempt to bludgeon one creature's mind with your will. One creature that you can see within range must succeed on a Wisdom saving throw or be charmed by you for the duration. If you or creatures that are friendly to you are fighting it, it has advantage on the saving throw. While charmed, you have a telepathic link with it as long as you are on the same plane."},"Dream":{"school":"Illusion","castTime":"1 minute","range":"Special","duration":"8 hours","components":"V, S, M","desc":"This spell shapes a creature's dreams. Choose a creature known to you as the target of this spell. The target must be on the same plane of existence as you. Creatures that don't sleep can't be contacted by this spell. You, or a willing creature you touch, enter a trance state, acting as a messenger. The messenger appears in the target's dreams and can converse with the target as long as it sleeps."},"Earthquake":{"school":"Evocation","castTime":"1 action","range":"500 feet","duration":"1 minute (concentration)","components":"V, S, M","desc":"You create a seismic disturbance at a point on the ground you can see within range. For the duration, an intense tremor rips through the ground in a 100-foot-radius circle centered on that point. Each creature on the ground in that area must make a Dexterity saving throw at the start of each of its turns. Concentration spells are disrupted on a failed Constitution saving throw."},"Elemental Weapon":{"school":"Transmutation","castTime":"1 action","range":"Touch","duration":"1 hour (concentration)","components":"V, S","desc":"A nonmagical weapon you touch becomes a magic weapon. Choose one of the following damage types: acid, cold, fire, lightning, or thunder. For the duration, the weapon has a +1 bonus to attack rolls and deals an extra 1d4 damage of the chosen type on a hit. At Higher Levels: higher slots increase the bonus and damage dice."},"Ensnaring Strike":{"school":"Conjuration","castTime":"1 bonus action","range":"Self","duration":"1 minute (concentration)","components":"V","desc":"The next time you hit a creature with a weapon attack before this spell ends, a writhing mass of thorny vines appears at the point of impact, and the target must succeed on a Strength saving throw or be restrained by the magical vines until the spell ends. A Large or larger creature has advantage on this saving throw. If the target succeeds, the vines shrivel away."},"Enthrall":{"school":"Enchantment","castTime":"1 action","range":"60 feet","duration":"1 minute","components":"V, S","desc":"You weave a distracting string of words, causing creatures of your choice that you can see within range and that can hear you to make a Wisdom saving throw. Any creature that can't be charmed succeeds on this saving throw automatically. On a failed save, the target has disadvantage on Wisdom (Perception) checks made to perceive any creature other than you until the spell ends."},"Etherealness":{"school":"Transmutation","castTime":"1 action","range":"Self","duration":"Up to 8 hours","components":"V, S","desc":"You step into the border regions of the Ethereal Plane, in the area where it overlaps with your current plane. You remain in the Border Ethereal for the duration or until you use your action to dismiss the spell. During this time, you can move in any direction. You can move through solid objects, but you treat them as difficult terrain."},"Eyebite":{"school":"Necromancy","castTime":"1 action","range":"Self","duration":"1 minute (concentration)","components":"V, S","desc":"For the spell's duration, your eyes become an inky void imbued with dread power. One creature of your choice within 60 feet of you that you can see must succeed on a Wisdom saving throw or be affected until the spell ends. On each of your turns until the spell ends, you can use your action to target another creature but can't target a creature again if it has succeeded on a saving throw against this casting. Choose Asleep, Panicked, or Sickened."},"Feeblemind":{"school":"Enchantment","castTime":"1 action","range":"150 feet","duration":"Instantaneous","components":"V, S, M","desc":"You blast the mind of a creature you can see within range, attempting to shatter its intellect and personality. The target takes 4d6 psychic damage and must make an Intelligence saving throw. On a failed save, the creature's Intelligence and Charisma scores become 1. The creature can't cast spells, activate magic items, understand language, or communicate in any intelligible way."},"Find Steed":{"school":"Conjuration","castTime":"10 minutes","range":"30 feet","duration":"Instantaneous","components":"V, S","desc":"You summon a spirit that assumes the form of an unusually intelligent, strong, and loyal steed, creating a long-lasting bond with it. Appearing in an unoccupied space within range, the steed takes on a form that you choose: a warhorse, a pony, a camel, an elk, or a mastiff. The steed has the statistics of the chosen form, though it is a celestial, fey, or fiend instead of its normal type."},"Find Traps":{"school":"Divination","castTime":"1 action","range":"120 feet","duration":"Instantaneous","components":"V, S","desc":"You sense the presence of any trap within range that is within line of sight. A trap, for the purpose of this spell, includes anything that would inflict a sudden or unexpected effect you consider harmful or undesirable, which was specifically intended as such by its creator. You learn the general nature of the danger presented by a trap you sense."},"Find the Path":{"school":"Divination","castTime":"1 minute","range":"Self","duration":"1 day (concentration)","components":"V, S, M","desc":"This spell allows you to find the shortest, most direct physical route to a specific fixed location that you are familiar with on the same plane of existence. If you name a destination on another plane of existence, a destination that moves (such as a mobile fortress), or a destination that isn't specific (such as 'a green dragon's lair'), the spell fails."},"Flesh to Stone":{"school":"Transmutation","castTime":"1 action","range":"60 feet","duration":"1 minute (concentration)","components":"V, S, M","desc":"You attempt to turn one creature that you can see within range into stone. If the target's body is made of flesh, the creature must make a Constitution saving throw. On a failed save, it is restrained as its flesh begins to harden. On a successful save, the creature isn't affected. A creature restrained by this spell must make another Constitution saving throw at the end of each of its turns."},"Forbiddance":{"school":"Abjuration","castTime":"10 minutes","range":"Touch","duration":"1 day","components":"V, S, M","desc":"You create a ward against magical travel that protects up to 40,000 square feet of floor space to a height of 30 feet above the floor. For the duration, creatures can't teleport into the area or use portals, such as those created by the gate spell, to enter the area. The spell proofs the area against planar travel, and therefore prevents creatures from accessing the area by way of the Astral Plane, Ethereal Plane, or similar means."},"Foresight":{"school":"Divination","castTime":"1 minute","range":"Touch","duration":"8 hours","components":"V, S, M","desc":"You touch a willing creature and bestow a limited ability to see into the immediate future. For the duration, the target can't be surprised and has advantage on attack rolls, ability checks, and saving throws. Additionally, other creatures have disadvantage on attack rolls against the target for the duration. This spell immediately ends if you cast it again before its duration ends."},"Gate":{"school":"Conjuration","castTime":"1 action","range":"60 feet","duration":"1 minute (concentration)","components":"V, S, M","desc":"You conjure a portal linking an unoccupied space you can see within range to a precise location on a different plane of existence. The portal is a circular opening, which you can make 5 to 20 feet in diameter. You can orient the portal in any direction you choose. The portal lasts for the duration. The portal has a front and a back on each plane where it appears. Travel through the portal is possible only by moving through its front."},"Geas":{"school":"Enchantment","castTime":"1 minute","range":"60 feet","duration":"30 days","components":"V","desc":"You place a magical command on a creature that you can see within range, forcing it to carry out some service or refrain from some action or course of activity as you decide. If the creature can understand you, it must succeed on a Wisdom saving throw or become charmed by you for the duration. While charmed by you, it takes 5d10 psychic damage each time it acts in a manner directly counter to your instructions."},"Gentle Repose":{"school":"Necromancy","castTime":"1 action","range":"Touch","duration":"10 days","components":"V, S, M","desc":"You touch a corpse or other remains. For the duration, the target is protected from decay and can't become undead. The spell also effectively extends the time limit on raising the target from the dead, since days spent under the influence of this spell don't count against the time limit of spells such as raise dead."},"Giant Insect":{"school":"Transmutation","castTime":"1 action","range":"30 feet","duration":"10 minutes (concentration)","components":"V, S","desc":"You transform up to ten centipedes, three spiders, five wasps, or one scorpion within range into giant versions of their natural forms for the duration. A centipede becomes a giant centipede, a spider becomes a giant spider, a wasp becomes a giant wasp, and a scorpion becomes a giant scorpion. Each creature obeys your verbal commands."},"Glibness":{"school":"Transmutation","castTime":"1 action","range":"Self","duration":"1 hour","components":"V","desc":"Until the spell ends, when you make a Charisma check, you can replace the number you roll with a 15. Additionally, no matter what you say, magic that would determine if you are telling the truth indicates that you are being truthful."},"Glyph of Warding":{"school":"Abjuration","castTime":"1 hour","range":"Touch","duration":"Until dispelled or triggered","components":"V, S, M","desc":"When you cast this spell, you inscribe a glyph that harms other creatures, either upon a surface (such as a table or a section of floor or wall) or within an object that can be closed (such as a book, a scroll, or a treasure chest) to conceal the glyph. The glyph can cover an area no larger than 10 feet in diameter. When triggered, the glyph releases a magical effect."},"Grasping Vine":{"school":"Conjuration","castTime":"1 bonus action","range":"30 feet","duration":"1 minute (concentration)","components":"V, S","desc":"You conjure a vine that sprouts from the ground in an unoccupied space of your choice that you can see within range. When you cast this spell, you can direct the vine to lash out at a creature within 30 feet of it that you can see. That creature must succeed on a Dexterity saving throw or be pulled 20 feet directly toward the vine."},"Guardian of Faith":{"school":"Conjuration","castTime":"1 action","range":"30 feet","duration":"8 hours","components":"V","desc":"A Large spectral guardian appears and hovers for the duration in an unoccupied space of your choice that you can see within range. The guardian occupies that space and is indistinct except for a gleaming sword and shield emblazoned with the symbol of your deity. Any creature hostile to you that moves to a space within 10 feet of the guardian for the first time on a turn must succeed on a Dexterity saving throw or take 20 radiant damage."},"Guards and Wards":{"school":"Abjuration","castTime":"10 minutes","range":"Touch","duration":"24 hours","components":"V, S, M","desc":"You create a ward that protects up to 2,500 square feet of floor space. The warded area can be up to 20 feet tall, and shaped as you desire. You can ward several stories of a stronghold by dividing the area among them, as long as you can walk into each contiguous area while you are casting the spell. When you cast this spell, you can specify individuals that are unaffected by any or all of the effects that you choose."},"Hail of Thorns":{"school":"Conjuration","castTime":"1 bonus action","range":"Self","duration":"1 minute (concentration)","components":"V","desc":"The next time you hit a creature with a ranged weapon attack before the spell ends, this spell creates a rain of thorns that sprouts from your ranged weapon or ammunition. In addition to the normal effect of the attack, the target and each creature within 5 feet of it must make a Dexterity saving throw. A creature takes 1d10 piercing damage on a failed save, or half as much on a successful one."},"Hallow":{"school":"Evocation","castTime":"24 hours","range":"Touch","duration":"Until dispelled","components":"V, S, M","desc":"You touch a point and infuse an area around it with holy (or unholy) power. The area can have a radius up to 60 feet, and the spell fails if the radius includes an area already under the effect of a hallow spell. The affected area is subject to the following effects. First, celestials, elementals, fey, fiends, and undead can't enter the area, nor can such creatures charm, frighten, or possess creatures within it."},"Hallucinatory Terrain":{"school":"Illusion","castTime":"10 minutes","range":"300 feet","duration":"24 hours","components":"V, S, M","desc":"You make natural terrain in a 150-foot cube in range look, sound, and smell like some other sort of natural terrain. Thus, open fields or a road can be made to resemble a swamp, hill, crevasse, or some other difficult or impassable terrain. A pond can be made to seem like a grassy meadow, a precipice like a gentle slope, or a rock-strewn gully like a wide and smooth road."},"Heroes Feast":{"school":"Conjuration","castTime":"10 minutes","range":"30 feet","duration":"Instantaneous","components":"V, S, M","desc":"You bring forth a great feast, including magnificent food and drink. The feast takes 1 hour to consume and disappears at the end of that time, and the beneficial effects don't set in until this hour is over. Up to twelve creatures can partake of the feast. A creature that partakes gains several benefits for 24 hours: immunity to poison and disease, advantage on Wisdom saving throws, and an increase to their hit point maximum and current hit points by 2d10."},"Holy Aura":{"school":"Abjuration","castTime":"1 action","range":"Self (30-foot radius)","duration":"1 minute (concentration)","components":"V, S, M","desc":"Divine light washes out from you and coalesces in a soft radiance in a 30-foot radius around you. Creatures of your choice in that radius when you cast this spell shed dim light in a 5-foot radius and have advantage on all saving throws, and other creatures have disadvantage on attack rolls against them. In addition, when a fiend or an undead hits an affected creature with a melee attack, the aura flashes with brilliant light."},"Holy Weapon":{"school":"Evocation","castTime":"1 bonus action","range":"Touch","duration":"1 hour (concentration)","components":"V, S","desc":"You imbue a weapon you touch with holy power. Until the spell ends, the weapon emits bright light in a 30-foot radius and dim light for an additional 30 feet. In addition, weapon attacks made with it deal an extra 2d8 radiant damage on a hit. If the weapon isn't already a magic weapon, it becomes one for the duration. As a bonus action on your turn, you can dismiss this spell and cause the weapon to emit a burst of radiance."},"Hunger of Hadar":{"school":"Conjuration","castTime":"1 action","range":"150 feet","duration":"1 minute (concentration)","components":"V, S, M","desc":"You open a gateway to the dark between the stars, a region infested with unknown horrors. A 20-foot-radius sphere of blackness and bitter cold appears, centered on a point with range and lasting for the duration. The void is filled with a cacophony of soft whispers and slurping noises that can be heard up to 30 feet away. No light, magical or otherwise, can illuminate the area, and creatures fully within the area are blinded."},"Hunters Mark":{"school":"Divination","castTime":"1 bonus action","range":"90 feet","duration":"1 hour (concentration)","components":"V","desc":"You choose a creature you can see within range and mystically mark it as your quarry. Until the spell ends, you deal an extra 1d6 damage to the target whenever you hit it with a weapon attack, and you have advantage on any Wisdom (Perception) or Wisdom (Survival) check you make to find it. If the target drops to 0 hit points before this spell ends, you can use a bonus action to mark a new creature."},"Imprisonment":{"school":"Abjuration","castTime":"1 minute","range":"30 feet","duration":"Until dispelled","components":"V, S, M","desc":"You create a magical restraint to hold a creature that you can see within range. The target must make a Wisdom saving throw. On a failed save, it is bound by the spell; if it succeeds, it is immune to this spell for 24 hours. While affected, the creature doesn't need to breathe, eat, or drink, and it doesn't age. You choose one of several forms of imprisonment: Burial, Chaining, Hedged Prison, Minimus Containment, or Slumber."},"Incendiary Cloud":{"school":"Conjuration","castTime":"1 action","range":"150 feet","duration":"1 minute (concentration)","components":"V, S","desc":"A swirling cloud of smoke shot through with white-hot embers appears in a 20-foot-radius sphere centered on a point within range. The cloud spreads around corners and is heavily obscured. It lasts for the duration or until a wind of moderate or greater speed (at least 10 miles per hour) disperses it. When the cloud appears, each creature in it must make a Dexterity saving throw, taking 10d8 fire damage on a failed save, or half on a success."},"Insect Plague":{"school":"Conjuration","castTime":"1 action","range":"300 feet","duration":"10 minutes (concentration)","components":"V, S, M","desc":"Swarming, biting locusts fill a 20-foot-radius sphere centered on a point you choose within range. The sphere spreads around corners. The sphere remains for the duration, and its area is lightly obscured. The sphere's area is difficult terrain. When the area appears, each creature in it must make a Constitution saving throw. A creature takes 4d10 piercing damage on a failed save, or half as much damage on a successful one."},"Legend Lore":{"school":"Divination","castTime":"10 minutes","range":"Self","duration":"Instantaneous","components":"V, S, M","desc":"Name or describe a person, place, or object. The spell brings to your mind a brief summary of the significant lore about the thing you named. The lore might consist of current tales, forgotten stories, or even secret lore that has never been widely known. If the thing you named isn't of legendary importance, you gain no information."},"Lesser Restoration":{"school":"Abjuration","castTime":"1 action","range":"Touch","duration":"Instantaneous","components":"V, S","desc":"You touch a creature and can end either one disease or one condition afflicting it. The condition can be blinded, deafened, paralyzed, or poisoned."},"Lightning Arrow":{"school":"Transmutation","castTime":"1 bonus action","range":"Self","duration":"1 minute (concentration)","components":"V, S","desc":"The next time you make a ranged weapon attack during the spell's duration, the weapon's ammunition, or the weapon itself if it's a thrown weapon, transforms into a bolt of lightning. Make the attack roll as normal. The target takes 4d8 lightning damage on a hit, or half as much damage on a miss, instead of the weapon's normal damage. Whether you hit or miss, each creature within 10 feet of the target must make a Dexterity saving throw."},"Locate Animals or Plants":{"school":"Divination","castTime":"1 action","range":"Self","duration":"Instantaneous","components":"V, S, M","desc":"Describe or name a specific kind of beast or plant. Concentrating on the voice of nature in your surroundings, you learn the direction and distance to the closest creature or plant of that kind within 5 miles, if any are present."},"Locate Creature":{"school":"Divination","castTime":"1 action","range":"Self","duration":"1 hour (concentration)","components":"V, S, M","desc":"Describe or name a creature that is familiar to you. You sense the direction to the creature's location, as long as that creature is within 1,000 feet of you. If the creature is moving, you know the direction of its movement. The spell can locate a specific creature known to you, or the nearest creature of a specific kind (such as a human or a unicorn). This spell can't locate a creature if running water at least 10 feet wide blocks a direct path between you and the creature."},"Locate Object":{"school":"Divination","castTime":"1 action","range":"Self","duration":"10 minutes (concentration)","components":"V, S, M","desc":"Describe or name an object that is familiar to you. You sense the direction to the object's location, as long as that object is within 1,000 feet of you. If the object is in motion, you know the direction of its movement. The spell can locate a specific object known to you, as long as you have seen it up close (within 30 feet) at least once."},"Magic Circle":{"school":"Abjuration","castTime":"1 minute","range":"10 feet","duration":"1 hour","components":"V, S, M","desc":"You create a 10-foot-radius, 20-foot-tall cylinder of magical energy centered on a point on the ground that you can see within range. Glowing runes appear wherever the cylinder intersects with the floor or other surface. Choose one or more of the following types of creatures: celestials, elementals, fey, fiends, or undead. The circle affects a creature of the chosen type in the following ways."},"Magic Mouth":{"school":"Illusion","castTime":"1 minute","range":"30 feet","duration":"Until dispelled","components":"V, S, M","desc":"You implant a message within an object in range, a message that is uttered when a trigger condition is met. Choose an object that you can see and that isn't being worn or carried by another creature. Then speak the message, which must be 25 words or less, though it can be delivered over as long as 10 minutes. When the trigger condition is met, a magical mouth appears on the object and recites the message in your voice."},"Major Image":{"school":"Illusion","castTime":"1 action","range":"120 feet","duration":"10 minutes (concentration)","components":"V, S, M","desc":"You create the image of an object, a creature, or some other visible phenomenon that is no larger than a 20-foot cube. The image appears at a spot that you can see within range and lasts for the duration. It seems completely real, including sounds, smells, and temperature appropriate to the thing depicted. You can't create sufficient heat or cold to cause damage, a sound loud enough to deal thunder damage or deafen a creature, or a smell that might sicken a creature."},"Mass Heal":{"school":"Evocation","castTime":"1 action","range":"60 feet","duration":"Instantaneous","components":"V, S","desc":"A flood of healing energy flows from you into injured creatures around you. You restore up to 700 hit points, divided as you choose among any number of creatures that you can see within range. Creatures healed by this spell are also cured of all diseases and any effect making them blinded or deafened. This spell has no effect on undead or constructs."},"Mass Suggestion":{"school":"Enchantment","castTime":"1 action","range":"60 feet","duration":"24 hours","components":"V, M","desc":"You suggest a course of activity (limited to a sentence or two) and magically influence up to twelve creatures of your choice that you can see within range and that can hear and understand you. Creatures that can't be charmed are immune to this effect. The suggestion must be worded in such a manner as to make the course of action sound reasonable."},"Maze":{"school":"Conjuration","castTime":"1 action","range":"60 feet","duration":"10 minutes (concentration)","components":"V, S","desc":"You banish a creature that you can see within range into a labyrinthine demiplane. The target remains there for the duration or until it escapes the maze. The target can use its action to attempt to escape. When it does so, it makes a DC 20 Intelligence check. If it succeeds, it escapes the maze."},"Meld into Stone":{"school":"Transmutation","castTime":"1 action","range":"Touch","duration":"8 hours","components":"V, S","desc":"You step into a stone object or surface large enough to fully contain your body, melding yourself and all the equipment you carry with the stone for the duration. Using your movement, you step into the stone at a point you can touch. Nothing of your presence remains visible or otherwise detectable by nonmagical senses."},"Meteor Swarm":{"school":"Evocation","castTime":"1 action","range":"1 mile","duration":"Instantaneous","components":"V, S","desc":"Blazing orbs of fire plummet to the ground at four different points you can see within range. Each creature in a 40-foot-radius sphere centered on each point you choose must make a Dexterity saving throw. The sphere spreads around corners. A creature takes 20d6 fire damage and 20d6 bludgeoning damage on a failed save, or half as much damage on a successful one. A creature in the area of more than one fiery burst is affected only once."},"Mind Blank":{"school":"Abjuration","castTime":"1 action","range":"Touch","duration":"24 hours","components":"V, S","desc":"Until the spell ends, one willing creature you touch is immune to psychic damage, any effect that would sense its emotions or read its thoughts, divination spells, and the charmed condition. The spell even foils wish spells and spells or effects of similar power used to affect the target's mind or to gain information about the target."},"Mirage Arcane":{"school":"Illusion","castTime":"10 minutes","range":"Sight","duration":"10 days","components":"V, S","desc":"You make terrain in an area up to 1 mile square look, sound, smell, and even feel like some other sort of terrain. The terrain's general shape remains the same, however. Open fields or a road can be made to resemble a swamp, hill, crevasse, or some other difficult or impassable terrain. A pond can be made to seem like a grassy meadow, a precipice like a gentle slope, or a rock-strewn gully like a wide and smooth road."},"Mislead":{"school":"Illusion","castTime":"1 action","range":"Self","duration":"1 hour (concentration)","components":"S","desc":"You become invisible at the same time that an illusory double of you appears where you are standing. The double lasts for the duration, but the invisibility ends if you attack or cast a spell. You can use your action to move your illusory double up to twice your speed and make it gesture, speak, and behave in whatever way you choose. You can see through its eyes and hear through its ears as if you were located where it is."},"Modify Memory":{"school":"Enchantment","castTime":"1 action","range":"30 feet","duration":"Concentration, up to 1 minute","components":"V, S","desc":"You attempt to reshape another creature's memories. One creature that you can see must make a Wisdom saving throw. If you are fighting the creature, it has advantage on the saving throw. On a failed save, the target becomes charmed by you for the duration. While charmed, you can affect one memory of an event that lasted no more than 10 minutes and that occurred within the past 24 hours."},"Move Earth":{"school":"Transmutation","castTime":"1 action","range":"120 feet","duration":"2 hours (concentration)","components":"V, S, M","desc":"Choose an area of terrain no larger than 40 feet on a side within range. You can reshape dirt, sand, or clay in the area in any manner you choose for the duration. You can raise or lower the area's elevation, create or fill in a trench, erect or flatten a wall, or form a pillar. The extent of any such changes can't exceed half the area's largest dimension."},"Nondetection":{"school":"Abjuration","castTime":"1 action","range":"Touch","duration":"8 hours","components":"V, S, M","desc":"For the duration, you hide a target that you touch from divination magic. The target can be a willing creature or a place or an object no larger than 10 feet in any dimension. The target can't be targeted by any divination magic or perceived through magical scrying sensors."},"Passwall":{"school":"Transmutation","castTime":"1 action","range":"30 feet","duration":"1 hour","components":"V, S, M","desc":"A passage appears at a point of your choice that you can see on a wooden, plaster, or stone surface (such as a wall, a ceiling, or a floor) within range, and lasts for the duration. You choose the opening's dimensions: up to 5 feet wide, 8 feet tall, and 20 feet deep. The passage creates no instability in a structure surrounding it."},"Phantasmal Force":{"school":"Illusion","castTime":"1 action","range":"60 feet","duration":"1 minute (concentration)","components":"V, S, M","desc":"You craft an illusion that takes root in the mind of a creature that you can see within range. The target must make an Intelligence saving throw. On a failed save, you create a phantasmal object, creature, or other visible phenomenon of your choice that is no larger than a 10-foot cube and that is perceivable only to the target for the duration."},"Planar Ally":{"school":"Conjuration","castTime":"10 minutes","range":"60 feet","duration":"Instantaneous","components":"V, S","desc":"You beseech an otherworldly entity for aid. The being must be known to you: a god, a primordial, a demon prince, or some other being of cosmic power. That entity sends a celestial, an elemental, or a fiend loyal to it to aid you, making the creature appear in an unoccupied space within range. If you know a specific creature's name, you can speak that name when you cast this spell to request that creature."},"Planar Binding":{"school":"Abjuration","castTime":"1 hour","range":"60 feet","duration":"24 hours","components":"V, S, M","desc":"With this spell, you attempt to bind a celestial, an elemental, a fey, or a fiend to your service. The creature must be within range for the entire casting of the spell. (Typically, the creature is first summoned into the center of an inverted magic circle in order to keep it trapped while this spell is cast.) At the completion of the casting, the target must make a Charisma saving throw. On a failed save, it is bound to serve you for the duration."},"Power Word Kill":{"school":"Enchantment","castTime":"1 action","range":"60 feet","duration":"Instantaneous","components":"V","desc":"You utter a word of power that can compel one creature you can see within range to die instantly. If the creature you choose has 100 hit points or fewer, it dies. Otherwise, the spell has no effect."},"Power Word Stun":{"school":"Enchantment","castTime":"1 action","range":"60 feet","duration":"Instantaneous","components":"V","desc":"You speak a word of power that overwhelms the mind of one creature you can see within range, leaving it dumbfounded. If the target has 150 hit points or fewer, it is stunned. Otherwise, the spell has no effect. The stunned target must make a Constitution saving throw at the end of each of its turns. On a successful save, the stunning effect ends."},"Prismatic Spray":{"school":"Evocation","castTime":"1 action","range":"Self (60-foot cone)","duration":"Instantaneous","components":"V, S","desc":"Eight rays of light flash from your hand. Each ray is a different color and has a different power and purpose. Each creature in a 60-foot cone must make a Dexterity saving throw. For each target, roll a d8 to determine which color ray affects it. Effects range from fire, acid, lightning, cold, poison, blinding, petrification, to a combination of effects."},"Prismatic Wall":{"school":"Abjuration","castTime":"1 action","range":"60 feet","duration":"10 minutes","components":"V, S","desc":"A shimmering, multicolored plane of light forms a vertical opaque wall up to 90 feet long, 30 feet high, and 1 inch thick centered on a point you can see within range. Alternatively, you can shape the wall into a sphere up to 30 feet in diameter centered on a point you choose within range. The wall remains in place for the duration. Any creature that tries to reach into or through the wall must make a Dexterity saving throw."},"Project Image":{"school":"Illusion","castTime":"1 action","range":"500 miles","duration":"1 day (concentration)","components":"V, S, M","desc":"You create an illusory copy of yourself that lasts for the duration. The copy can appear at any location within range that you have seen before, regardless of intervening obstacles. The illusion looks and sounds like you but is intangible. If the illusion takes any damage, it disappears, and the spell ends."},"Protection from Poison":{"school":"Abjuration","castTime":"1 action","range":"Touch","duration":"1 hour","components":"V, S","desc":"You touch a creature. If it is poisoned, you neutralize the poison. If more than one poison afflicts the target, you neutralize one poison that you know is present, or you neutralize one at random. For the duration, the target has advantage on saving throws against being poisoned, and it has resistance to poison damage."},"Purify Food and Drink":{"school":"Transmutation","castTime":"1 action","range":"10 feet","duration":"Instantaneous","components":"V, S","desc":"All nonmagical food and drink within a 5-foot-radius sphere centered on a point of your choice within range is purified and rendered free of poison and disease."},"Ray of Sickness":{"school":"Necromancy","castTime":"1 action","range":"60 feet","duration":"Instantaneous","components":"V, S","desc":"A ray of sickening greenish energy lashes out toward a creature within range. Make a ranged spell attack against the target. On a hit, the target takes 2d8 poison damage and must make a Constitution saving throw. On a failed save, it is also poisoned until the end of your next turn. At Higher Levels: When you cast this spell using a spell slot of 2nd level or higher, the damage increases by 1d8 for each slot level above 1st."},"Reincarnate":{"school":"Transmutation","castTime":"1 hour","range":"Touch","duration":"Instantaneous","components":"V, S, M","desc":"You touch a dead humanoid or a piece of a dead humanoid. Provided that the creature has been dead no longer than 10 days, the spell forms a new adult body for it and then calls the soul to enter that body. If the target's soul isn't free or willing to do so, the spell fails. The magic fashions a new body for the creature to inhabit, which likely causes the creature's race to change."},"Resistance":{"school":"Abjuration","castTime":"1 action","range":"Touch","duration":"1 minute (concentration)","components":"V, S, M","desc":"You touch one willing creature. Once before the spell ends, the target can roll a d4 and add the number rolled to one saving throw of its choice. It can roll the die before or after making the saving throw. The spell then ends."},"Sanctuary":{"school":"Abjuration","castTime":"1 bonus action","range":"30 feet","duration":"1 minute","components":"V, S, M","desc":"You ward a creature within range against attack. Until the spell ends, any creature who targets the warded creature with an attack or a harmful spell must first make a Wisdom saving throw. On a failed save, the creature must choose a new target or lose the attack or spell. This spell doesn't protect the warded creature from area effects, such as the explosion of a fireball."},"Searing Smite":{"school":"Evocation","castTime":"1 bonus action","range":"Self","duration":"1 minute (concentration)","components":"V","desc":"The next time you hit a burning creature with a melee weapon attack during the spell's duration, your weapon flares with white-hot intensity, and the attack deals an extra 1d6 fire damage to the target and causes the target to ignite in flames. At the start of each of its turns until the spell ends, the target must make a Constitution saving throw, taking 1d6 fire damage on a failed save."},"Seeming":{"school":"Illusion","castTime":"1 action","range":"30 feet","duration":"8 hours","components":"V, S","desc":"This spell allows you to change the appearance of any number of creatures that you can see within range. You give each target you choose a new, illusory appearance. An unwilling target can make a Charisma saving throw, and if it succeeds, it is unaffected by this spell. The spell disguises physical appearance as well as clothing, armor, weapons, and equipment."},"Sequester":{"school":"Transmutation","castTime":"1 action","range":"Touch","duration":"Until dispelled","components":"V, S, M","desc":"By means of this spell, a willing creature or an object can be hidden away, safe from detection for the duration. When you cast the spell and touch the target, it becomes invisible and can't be targeted by divination spells or perceived through scrying sensors created by divination spells. If the target is a creature, it falls into a state of suspended animation."},"Shapechange":{"school":"Transmutation","castTime":"1 action","range":"Self","duration":"1 hour (concentration)","components":"V, S, M","desc":"You assume the form of a different creature for the duration. The new form can be of any creature with a challenge rating equal to your level or lower. The creature can't be a construct or an undead, and you must have seen the sort of creature at least once. You transform into the average example of that creature, using its game statistics."},"Silent Image":{"school":"Illusion","castTime":"1 action","range":"60 feet","duration":"10 minutes (concentration)","components":"V, S, M","desc":"You create the image of an object, a creature, or some other visible phenomenon that is no larger than a 15-foot cube. The image appears at a spot within range and lasts for the duration. The image is purely visual; it isn't accompanied by sound, smell, or other sensory effects. You can use your action to cause the image to move to any spot within range."},"Simulacrum":{"school":"Illusion","castTime":"12 hours","range":"Touch","duration":"Until dispelled","components":"V, S, M","desc":"You shape an illusory duplicate of one beast or humanoid that is within range for the entire casting time of the spell. The duplicate is a creature, partially real and formed from ice or snow, and it can take actions and otherwise be affected as a normal creature. It appears to be the same as the original, but it has half the creature's hit point maximum and is formed without any equipment."},"Sleet Storm":{"school":"Conjuration","castTime":"1 action","range":"150 feet","duration":"1 minute (concentration)","components":"V, S, M","desc":"Until the spell ends, freezing rain and sleet fall in a 20-foot-tall cylinder with a 40-foot radius centered on a point you choose within range. The area is heavily obscured, and exposed flames in the area are doused. The ground in the area is covered with slick ice, making it difficult terrain. When a creature enters the spell's area for the first time on a turn or starts its turn there, it must make a Dexterity saving throw or fall prone."},"Speak with Plants":{"school":"Transmutation","castTime":"1 action","range":"Self (30-foot radius)","duration":"10 minutes","components":"V, S","desc":"You imbue plants within 30 feet of you with limited sentience and animation, giving them the ability to communicate with you and follow your simple commands. You can question plants about events in the spell's area within the past day, gaining information about creatures that have passed, weather, and other circumstances. You can also turn difficult terrain caused by plant growth (such as thickets and undergrowth) into ordinary terrain that lasts for the duration."},"Staggering Smite":{"school":"Evocation","castTime":"1 bonus action","range":"Self","duration":"1 minute (concentration)","components":"V","desc":"The next time you hit a creature with a melee weapon attack during this spell's duration, your weapon pierces both body and mind, and the attack deals an extra 4d6 psychic damage to the target. The target must make a Wisdom saving throw. On a failed save, it has disadvantage on attack rolls and ability checks, and can't take reactions, until the end of its next turn."},"Stone Shape":{"school":"Transmutation","castTime":"1 action","range":"Touch","duration":"Instantaneous","components":"V, S, M","desc":"You touch a stone object of Medium size or smaller or a section of stone no more than 5 feet in any dimension and form it into any shape that suits your purpose. So, for example, you could shape a large rock into a weapon, idol, or coffer, or make a small passage through a wall, as long as the wall is less than 5 feet thick."},"Storm of Vengeance":{"school":"Conjuration","castTime":"1 action","range":"Sight","duration":"1 minute (concentration)","components":"V, S","desc":"A churning storm cloud forms, centered on a point you can see and spreading to a radius of 360 feet. Lightning flashes in the area, thunder booms, and strong winds roar. Each creature under the cloud (no more than 5,000 feet beneath the cloud) when it appears must make a Constitution saving throw. On a failed save, a creature takes 2d6 thunder damage and becomes deafened for 5 minutes."},"Sunburst":{"school":"Evocation","castTime":"1 action","range":"150 feet","duration":"Instantaneous","components":"V, S, M","desc":"Brilliant sunlight flashes in a 60-foot radius centered on a point you choose within range. Each creature in that light must make a Constitution saving throw. On a failed save, a creature takes 12d6 radiant damage and is blinded for 1 minute. On a successful save, it takes half as much damage and isn't blinded by this spell. Undead and oozes have disadvantage on this saving throw."},"Swift Quiver":{"school":"Transmutation","castTime":"1 bonus action","range":"Touch","duration":"1 minute (concentration)","components":"V, S, M","desc":"You transmute your quiver so it produces an endless supply of nonmagical ammunition, which seems to leap into your hand when you reach for it. On each of your turns until the spell ends, you can use a bonus action to make two attacks with a weapon that uses ammunition from the quiver. Each time you make such a ranged attack, your quiver magically replaces the ammunition you used."},"Symbol":{"school":"Abjuration","castTime":"1 minute","range":"Touch","duration":"Until dispelled or triggered","components":"V, S, M","desc":"When you cast this spell, you inscribe a harmful glyph either on a surface (such as a section of floor, a wall, or a table) or within an object that can be closed to conceal the glyph (such as a book, a scroll, or a treasure chest). The glyph can cover an area no larger than 10 feet in diameter. When triggered, the glyph affects all creatures within 60 feet of it."},"Teleport":{"school":"Conjuration","castTime":"1 action","range":"10 feet","duration":"Instantaneous","components":"V","desc":"This spell instantly transports you and up to eight willing creatures of your choice that you can see within range, or a single object that you can see within range, to a destination you select. If you target an object, it must be able to fit entirely inside a 10-foot cube, and it can't be held or carried by an unwilling creature. The destination you choose must be known to you, and it must be on the same plane of existence as you."},"Teleportation Circle":{"school":"Conjuration","castTime":"1 minute","range":"10 feet","duration":"1 round","components":"V, M","desc":"As you cast the spell, you draw a 10-foot-diameter circle on the ground inscribed with sigils that link your location to a permanent teleportation circle of your choice whose sigil sequence you know and that is on the same plane of existence as you. A shimmering portal opens within the circle you drew and remains open until the end of your next turn."},"Thorn Whip":{"school":"Transmutation","castTime":"1 action","range":"30 feet","duration":"Instantaneous","components":"V, S, M","desc":"You create a long, vine-like whip covered in thorns that lashes out at your command toward a creature in range. Make a melee spell attack against the target. If the attack hits, the creature takes 1d6 piercing damage, and if the creature is Large or smaller, you pull the creature up to 10 feet closer to you."},"Thunderous Smite":{"school":"Evocation","castTime":"1 bonus action","range":"Self","duration":"1 minute (concentration)","components":"V","desc":"The first time you hit with a melee weapon attack during this spell's duration, your weapon rings with thunder that is audible within 300 feet of you, and the attack deals an extra 2d6 thunder damage to the target. Additionally, if the target is a creature, it must succeed on a Strength saving throw or be pushed 10 feet away from you and knocked prone."},"Time Stop":{"school":"Transmutation","castTime":"1 action","range":"Self","duration":"Instantaneous","components":"V","desc":"You briefly stop the flow of time for everyone but yourself. No time passes for other creatures, while you take 1d4 + 1 turns in a row, during which you can use actions and move as normal. This effect ends if one of the actions you use during this period, or any effects that you create during this period, affects a creature other than you or an object being worn or carried by someone other than you."},"Transport via Plants":{"school":"Conjuration","castTime":"1 action","range":"10 feet","duration":"1 round","components":"V, S","desc":"This spell creates a magical link between a Large or larger inanimate plant within range and another plant, at any distance, on the same plane of existence. You must have seen or touched the destination plant at least once before. For the duration, any creature can step into the target plant and exit from the destination plant by using 5 feet of movement."},"Tree Stride":{"school":"Conjuration","castTime":"1 action","range":"Self","duration":"1 minute (concentration)","components":"V, S","desc":"You gain the ability to enter a tree and move from inside it to inside another tree of the same kind within 500 feet. Both trees must be living and at least the same size as you. You must use 5 feet of movement to enter a tree. You instantly know the location of all other trees of the same kind within 500 feet and, as part of the move used to enter the tree, can either pass into one of those trees or step out of the tree you're in."},"True Resurrection":{"school":"Necromancy","castTime":"1 hour","range":"Touch","duration":"Instantaneous","components":"V, S, M","desc":"You touch a creature that has been dead for no longer than 200 years and that died for any reason except old age. If the creature's soul is free and willing, the creature is restored to life with all its hit points. This spell closes all wounds, neutralizes any poison, cures all diseases, and lifts any curses afflicting the creature when it died. The spell can even provide a new body if the original no longer exists."},"Unseen Servant":{"school":"Conjuration","castTime":"1 action","range":"60 feet","duration":"1 hour","components":"V, S, M","desc":"This spell creates an invisible, mindless, shapeless, Medium force that performs simple tasks at your command until the spell ends. The servant springs into existence in an unoccupied space on the ground within range. It has AC 10, 1 hit point, and a Strength of 2, and it can't attack. If it drops to 0 hit points, the spell ends."},"Wall of Ice":{"school":"Evocation","castTime":"1 action","range":"120 feet","duration":"10 minutes (concentration)","components":"V, S, M","desc":"You create a wall of ice on a solid surface within range. The wall is 1 foot thick and up to 30 feet long and 10 feet high, or it's a hemispherical dome up to 20 feet in diameter. The wall lasts for the duration. When the wall appears, each creature within its area must make a Dexterity saving throw. On a failed save, a creature takes 10d6 cold damage, or half as much on a successful save."},"Wall of Stone":{"school":"Evocation","castTime":"1 action","range":"120 feet","duration":"10 minutes (concentration)","components":"V, S, M","desc":"A nonmagical wall of solid stone springs into existence at a point you choose within range. The wall is 6 inches thick and is composed of ten 10-foot-by-10-foot panels. Each panel must be contiguous with at least one other panel. Alternatively, you can create 10-foot-by-20-foot panels that are only 3 inches thick. The wall lasts until the spell ends or is destroyed."},"Wall of Thorns":{"school":"Conjuration","castTime":"1 action","range":"120 feet","duration":"10 minutes (concentration)","components":"V, S, M","desc":"You create a wall of tough, pliable, tangled brush bristling with needle-sharp thorns. The wall appears within range on a solid surface and lasts for the duration. You choose to make the wall up to 60 feet long, 10 feet high, and 5 feet thick or a circle that has a 20-foot diameter and is up to 20 feet high and 5 feet thick. The wall blocks line of sight."},"Water Breathing":{"school":"Transmutation","castTime":"1 action","range":"30 feet","duration":"24 hours","components":"V, S, M","desc":"This spell grants up to ten willing creatures you can see within range the ability to breathe underwater until the spell ends. Affected creatures also retain their normal mode of respiration."},"Weird":{"school":"Illusion","castTime":"1 action","range":"120 feet","duration":"1 minute (concentration)","components":"V, S","desc":"Drawing on the deepest fears of a group of creatures, you create illusory creatures in their minds, visible only to them. Each creature in a 30-foot-radius sphere centered on a point of your choice within range must make a Wisdom saving throw. On a failed save, the creature becomes frightened for the duration. The illusion calls on the creature's deepest fears, manifesting its worst nightmares as an implacable threat."},"Wind Walk":{"school":"Transmutation","castTime":"1 minute","range":"30 feet","duration":"8 hours","components":"V, S, M","desc":"You and up to ten willing creatures you can see within range assume a gaseous form for the duration, appearing as wisps of cloud. While in this cloud form, a creature has a flying speed of 300 feet and has resistance to damage from nonmagical weapons. The only actions a creature can take in this form are the Dash action or to revert to its normal form."},"Wind Wall":{"school":"Evocation","castTime":"1 action","range":"120 feet","duration":"1 minute (concentration)","components":"V, S, M","desc":"A wall of strong wind rises from the ground at a point you choose within range. You can make the wall up to 50 feet long, 15 feet high, and 1 foot thick. You can shape the wall in any way you choose so long as it makes one continuous path along the ground. The wall lasts for the duration. When the wall appears, each creature within its area must make a Strength saving throw."},"Word of Recall":{"school":"Conjuration","castTime":"1 action","range":"5 feet","duration":"Instantaneous","components":"V","desc":"You and up to five willing creatures within 5 feet of you instantly teleport to a previously designated sanctuary. You and any creatures that teleport with you appear in the nearest unoccupied space to the spot you designated when you prepared your sanctuary."},"Zone of Truth":{"school":"Enchantment","castTime":"1 action","range":"60 feet","duration":"10 minutes","components":"V, S","desc":"You create a magical zone that guards against deception in a 15-foot-radius sphere centered on a point of your choice within range. Until the spell ends, a creature that enters the spell's area for the first time on a turn or starts its turn there must make a Charisma saving throw. On a failed save, a creature can't speak a deliberate lie while in the radius."}};
